,["oi"]=2,["soloSpeedrun"]=true,["fromId"]=460006,["t"]="collect",["id"]="solo:forever/alliance/02-westfall:33:1",["quest"]=92742,["y"]=0.382,["x"]=0.461,["item"]=254547,["from"]="Molsen Farm Water Well",["title"]="Testing the Wells",["count"]=1,["fromKind"]="object",["note"]="Fill the vial at the farm's well"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1436,["itemName"]="Gnoll Paw",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/02-westfall:goal:35:1",["t"]="collect",["item"]=725,["y"]=0.146,["x"]=0.447,["title"]="Patrolling Westfall",["lvl"]=13,["note"]="Gnoll Paws",["fromNpcsAt"]="1,2;1,2,3;1,2;2,5;1,2;2,5;5,2,6;2,5;4",["quest"]=102,["count"]=8}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/02-westfall:step:35",["text"]="The gnoll hills",["detail"]="North to the hills above Jangolode Mine: Riverpaw Gnolls and Scouts (level 11-13) roam there, east toward the The Jansen Stead. The gnolls further south and west are 13-19: stay in the north hills.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer."},{["goals"]={{["map"]=1436,["itemName"]="Longshore Murloc Gill",["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/02-westfall:36:1",["t"]="collect",["y"]=0.105,["x"]=0.425,["title"]="Murloc Gills",["item"]=254548,["quest"]=92744,["count"]=7,["spread"]=true,["note"]="Longshore Murloc Gills"},{["map"]=1436,["itemName"]="Murloc Eye",["oi"]=2,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/02-westfall:36:2",["t"]="collect",["y"]=0.105,["x"]=0.425,["title"]="Westfall Stew",["item"]=730,["quest"]=38,["spread"]=true,["count"]=3}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/02-westfall:36",["text"]="The Longshore murlocs",["detail"]="Murloc Coastrunners and Raiders line the north coast from above the mine east toward the The Jansen Stead: work along the beach eastward. They flee at low health: pull one at a time."},{["goals"]={{["map"]=1436,["itemName"]="Furlbrow's Pocket Watch",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=290,["t"]="collect",["id"]="solo:forever/alliance/02-westfall:37:1",["quest"]=64,["y"]=0.1928,["x"]=0.49329999999999996,["item"]=841,["from"]="Furlbrow's Wardrobe",["title"]="The Forgotten Heirloom",["count"]=1,["fromKind"]="object",["note"]="Furlbrow's Wardrobe; inside"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/02-westfall:37",["text"]="Furlbrow's Wardrobe",["detail"]="Furlbrow's Wardrobe stands in the ruined house east of the mine, on the way to the The Jansen Stead.\nCareful: Two Defias stand guard inside, one of them the level 15 named Benny Blaanco. They are linked, so attacking either one brings both."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/02-westfall:step:38",["text"]="The Jansen Stead",["goals"]={{["map"]=1436,["itemName"]="Handful of Oats",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=2724,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/02-westfall:goal:38:1",["fromKind"]="object",["y"]=0.207,["x"]=0.569,["title"]="Poor Old Blanchy",["from"]="Sack of Oats",["item"]=1528,["note"]="Sacks of Oats in the fields around the farm",["quest"]=151,["count"]=8},{["map"]=1436,["itemName"]="Jansen Stead Water Sample",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=460005,["t"]="collect",["id"]="solo:forever/alliance/02-westfall:38:2",["quest"]=92742,["y"]=0.18600000000000003,["x"]=0.5660000000000001,["item"]=254546,["from"]="Jansen Stead Water Well",["title"]="Testing the Wells",["count"]=1,["fromKind"]="object",["note"]="Fill the vial at the well"},{["map"]=1436,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/02-westfall:38:3",["t"]="turnin",["npc"]=237,["npcName"]="Farmer Furlbrow",["x"]=0.5995,["title"]="The Forgotten Heirloom",["quest"]=64,["y"]=0.1936},{["map"]=1436,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/02-westfall:38:4",["t"]="turnin",["npc"]=238,["npcName"]="Verna Furlbrow",["x