l"]=true,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:goal:1:7",["t"]="accept",["npc"]=3694,["npcName"]="Sentinel Selarin",["x"]=0.39280000000000004,["title"]="Trek to Ashenvale",["minLevel"]=15,["y"]=0.4346,["qlvl"]=19,["quest"]=990,["note"]="Sentinel Selarin, beside Terenthis if she is there: for Raene Wolfrunner in Astranaar, in the next guide"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:step:1",["text"]="Auberdine",["detail"]="From the dock (or the inn, if you used your Hearthstone), up to the north end of the village first (Thundris Windweaver, Alanndarian Nightsong by the moonwell, Archaeologist Hollee), then down the main street: the WANTED poster outside the inn, Terenthis at its east end, where the road leaves south. Sentinel Selarin (Trek to Ashenvale) is beside Terenthis only for a few minutes at a time: she comes shortly after someone hands in Volcor's escort and leaves again about 5 minutes later. If she isn't there, don't wait: the guide offers her quest again when you hand in Volcor's escort to Terenthis yourself. Changing layer can also find her."},{["goals"]={{["map"]=1439,["itemName"]="Earthroot",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:goal:2:1",["t"]="collect",["y"]=0.3951,["x"]=0.4142,["title"]="Gathering the Cure",["item"]=2449,["quest"]=6123,["only"]={["races"]={"NightElf","Skyborne"}},["count"]=5},{["map"]=1439,["itemName"]="Lunar Fungus",["oi"]=2,["soloSpeedrun"]=true,["fromId"]=177750,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:goal:2:2",["only"]={["races"]={"NightElf","Skyborne"}},["y"]=0.45770000000000005,["x"]=0.4321,["title"]="Gathering the Cure",["from"]="Lunar Fungal Bloom",["item"]=15851,["fromKind"]="object",["quest"]=6123,["count"]=12}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:step:2",["text"]="Lunar Fungus and Earthroot",["only"]={["classes"]={"DRUID"},["races"]={"NightElf","Skyborne"}},["detail"]="On the way south to the Grove: the Lunar Fungal Blooms grow in the moonkin caves in the hills just east of Auberdine, a short way off the road; the moonkin there are irritable. Earthroot needs Herbalism: herbalists pick it all over Darkshore, anyone else brings it from Stormwind (Maria Lumere) or the Auction House."},{["goals"]={{["map"]=1439,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/03-darkshore-return:2:1",["t"]="turnin",["npc"]=3616,["soloWhen"]={{["k"]="onquest",["q"]={952}}},["npcName"]="Onu",["x"]=0.4355,["title"]="Grove of the Ancients",["y"]=0.7629,["quest"]=952,["only"]={["races"]={"NightElf"}}}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/03-darkshore-return:2",["text"]="Onu",["soloWhen"]={{["k"]="onquest",["q"]={952}}}},{["goals"]={{["map"]=1439,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/03-darkshore-return:3:1",["t"]="turnin",["npc"]=3616,["npcName"]="Onu",["x"]=0.4355,["title"]="Onu",["quest"]=948,["y"]=0.7629},{["map"]=1439,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/03-darkshore-return:3:2",["t"]="accept",["npc"]=3616,["y"]=0.7629,["x"]=0.4355,["title"]="The Master's Glaive",["minLevel"]=12,["pre"]={948},["qlvl"]=17,["quest"]=944,["npcName"]="Onu"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/03-darkshore-return:3",["text"]="Onu",["detail"]="Onu is the ancient at the Grove; Arbal and Kerlonian Evershade sleep beside him."},{["goals"]={{["itemName"]="Grizzled Scalp",["item"]=5414,["quest"]=1003,["map"]=1439,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=2165,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:goal:5:1",["count"]=4,["y"]=0.813,["x"]=0.41100000000000003,["title"]="Buzzbox 525",["from"]="Grizzled Thistle Bear",["fromAlso"]="Den Mother",["note"]="Grizzled Scalps",["fromKind"]="npc",["fromAlsoId"]=6788},{["map"]=1439,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/03-darkshore-return:5:2",["t"]="turnin",["y"]=0.8056,["x"]=0.4139,["title"]="Buzzbox 525",["objName"]="Buzzbox 525",["quest"]=1003,["object"]=17185}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:step:5",["text"]="The Grove of the Ancients",["detail"]="Grizzled Thistle Bears roam the hills around the Grove; Buzzbox 525 stands west of it among them."},{["goals"]={{["itemName"]="Fine Moonstalker Pelt",["item"]=5386,["quest"]=986,["map"]=1439,["fromId"]=2071,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:goal:6:1",["fromAlso"]="Moonstalker Sire",["t"]="collect",["title"]="A Lost Master",["y"]=0.8136,["x"]=0.39890000000000003,["count"]=5,["from"]="Moonstalker Matriarch",["note"]="Fine Moonstalker Pelts",["spread"]=true,["fromKind"]="npc",["fromAlsoId"]=2237},{["map"]=1439,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/03-darkshore-return:6:2",["t"]="accept",["npc"]=3584,["npcName"]="Therylune",["x"]=0.3864,["escort"]=true,["minLevel"]=10,["y"]=0.8733,["qlvl"]=18,["quest"]=945,["title"]="Therylune's Escape"},{["note"]="Escort her out of the glaive; Therysil takes the turn-in in Ashenvale",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/03-darkshore-return:goal:6:3",["t"]="complete",["objs"]={{["count"]=1,["text"]="Escort Therylune away from the Master's Glaive"}},["title"]="Therylune's Escape",["escort"]=true,["quest"]=945,["carriedTo"]="forever/alliance/06-ashenvale"},{["itemName"]="Book: The Powers Below",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/03-darkshore-return:6:4",["t"]="accept",["title"]="The Powers Below",["item"]=5352,["optional"]=true,["minLevel"]=10,["qlvl"]=18,["quest"]=968,["note"]="Only if a Disciple or Thug dropped Book: The Powers Below: right-click it"},{["soloSpeedrun"]=true,["