={"NightElf","Skyborne"}},["soloWhen"]={{["k"]="onquest",["q"]={272}}}},{["soloWhen"]={{["k"]="onquest",["q"]={272}}},["goals"]={{["map"]=1436,["itemName"]="Half Pendant of Aquatic Endurance",["soloSpeedrun"]=true,["fromId"]=177790,["t"]="collect",["soloWhen"]={{["k"]="onquest",["q"]={272}}},["y"]=0.3318,["x"]=0.1794,["item"]=15882,["from"]="Strange Lockbox",["id"]="solo:forever/alliance/04-redridge-mountains:7:1",["count"]=1,["fromKind"]="object",["note"]="Half Pendant of Aquatic Endurance: the Strange Lockbox"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/04-redridge-mountains:step:5",["text"]="Half Pendant of Aquatic Endurance",["only"]={["classes"]={"DRUID"},["races"]={"NightElf","Skyborne"}},["detail"]="Fly to Sentinel Hill and head north-west to the coast: the Strange Lockbox lies on the sea floor off the shore. Then head east along the road through Elwynn."},{["id"]="solo:forever/alliance/04-redridge-mountains:9",["text"]="Elwynn Forest",["goals"]={{["map"]=1429,["x"]=0.652,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/04-redridge-mountains:9:1",["text"]="The Tower of Azora",["y"]=0.6970000000000001,["t"]="goto"}},["soloSpeedrun"]=true},{["id"]="solo:forever/alliance/04-redridge-mountains:10",["text"]="Theocritus",["goals"]={{["map"]=1429,["note"]="On the top floor",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/04-redridge-mountains:10:1",["t"]="accept",["npc"]=313,["npcName"]="Theocritus",["x"]=0.6522,["title"]="A Watchful Eye",["minLevel"]=20,["qlvl"]=21,["quest"]=94,["y"]=0.6970999999999999}},["soloSpeedrun"]=true},{["soloWhen"]={{["k"]="onquest",["q"]={1786,1787}}},["goals"]={{["map"]=1429,["itemName"]="Symbol of Life",["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/04-redridge-mountains:11:1",["t"]="use",["soloWhen"]={{["k"]="onquest",["q"]={1786,1787}}},["y"]=0.5141,["x"]=0.726,["title"]="The Tome of Divinity",["item"]=6866,["quest"]=1786,["only"]={["races"]={"Human"}},["note"]="Use the 