=0.22030000000000002,["x"]=0.2661,["title"]="What Is Love?",["from"]="Wooden Figurine",["count"]=1,["note"]="Wooden Figurine, north of Maestra's Post",["fromKind"]="object",["carriedTo"]="forever/alliance/30-40/05-arathi-highlands"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/04-stranglethorn-vale:step:30",["text"]="Heartswood",["only"]={["classes"]={"WARLOCK"}},["detail"]="From Astranaar head north-west into the hills: the Heartswood is a glowing tree north of the road to Maestra's Post. If you took What Is Love?, the Wooden Figurine lies in a house among the trees north of Maestra's Post (26.6,22.0). Then take the road west to Stonetalon."},{["goals"]={{["map"]=1442,["x"]=0.3,["t"]="goto",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/04-stranglethorn-vale:goal:31:1",["text"]="The road to Nijel's Point",["y"]=0.765,["soloWhen"]={{["neg"]=true,["k"]="zone",["name"]="Desolace",["area"]=405}}}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/04-stranglethorn-vale:step:31",["text"]="Stonetalon Mountains",["soloWhen"]={{["neg"]=true,["k"]="zone",["name"]="Desolace",["area"]=405}}}},["max"]=34,["soloSpeedrun"]=true,["min"]=32,["availability"]="source-listed",["name"]="Stranglethorn Vale (solo 32-34)",["category"]="Leveling",["zoneName"]="Stranglethorn Vale",["faction"]="Alliance",["refreshRevision"]="forever-20261117-b753c783",["next"]="solo:forever/alliance/30-40/02-desolace"} end},
