p"]=1446},{["npcName"]="Brinna Valanaar",["x"]=0.12,["y"]=0.7837999999999999,["npc"]=14301,["map"]=1447},{["npcName"]="Mylini Frostmoon",["x"]=0.6241,["y"]=0.25780000000000003,["npc"]=15315,["map"]=1448},{["npcName"]="Gibbert",["x"]=0.441,["y"]=0.0719,["npc"]=3000,["map"]=1449},{["npcName"]="Geenia Sunshadow",["x"]=0.52,["y"]=0.3289,["npc"]=4184,["map"]=1450},{["npcName"]="Vargus",["x"]=0.5123,["y"]=0.3886,["npc"]=15176,["map"]=1451},{["npcName"]="Nixxrak",["x"]=0.6162,["y"]=0.3787,["npc"]=11182,["map"]=1452},{["npcName"]="Cylania",["x"]=0.5924,["y"]=0.4636,["npc"]=4164,["map"]=1457},{["npcName"]="Merelyssa",["x"]=0.6536,["y"]=0.5974,["npc"]=4171,["map"]=1457},{["npcName"]="Vinasia",["x"]=0.6067,["y"]=0.7248,["npc"]=4175,["map"]=1457},{["npcName"]="Andrus",["x"]=0.5613,["y"]=0.8891,["npc"]=4234,["map"]=1457},{["npcName"]="Cyridan",["x"]=0.529,["y"]=0.805,["npc"]=4236,["map"]=1457},{["npcName"]="Lana Thunderbrew",["x"]=0.4341,["y"]=0.1564,["npc"]=4257,["map"]=1459},{["npcName"]="Toron Rockhoof",["x"]=0.6888,["map"]=2482,["npc"]=243855,["y"]=0.48350000000000004},{["npcName"]="Trigg Ironhand",["x"]=0.1562,["map"]=2482,["npc"]=265866,["y"]=0.5075999999999999},{["npcName"]="Chagrak Hammerstrike",["x"]=0.1349,["map"]=2482,["npc"]=265883,["y"]=0.5097},{["npcName"]="Destin Thriceforged",["x"]=0.4343,["map"]=2521,["npc"]=251364,["y"]=0.235},{["npcName"]="Aedi Thriceforged",["x"]=0.44880000000000003,["map"]=2521,["npc"]=251913,["y"]=0.4437},{["npcName"]="Daeann Steelwind",["x"]=0.6547,["map"]=2521,["npc"]=252479,["y"]=0.8028},{["npcName"]="Railee Thriceforged",["x"]=0.5898,["map"]=2521,["npc"]=257422,["y"]=0.7545999999999999},{["npcName"]="Genn Fairweather",["x"]=0.5383,["map"]=2521,["npc"]=265756,["y"]=0.8133}},["soloSpeedrun"]=true}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:43",["text"]="Refuge Pointe",["detail"]="West along the road to Refuge Pointe."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:44",["text"]="Circle of West Binding",["superseded"]=true},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:45",["text"]="Faldir's Cove",["superseded"]=true,["detail"]="A group stop: two level 40 water elementals ambush Professor Phizzlethorpe's escort, and the Daggerspine naga in the reef are 38-40, with Sorceresses among them. Grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nSouth along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:46",["text"]="Phizzlethorpe",["superseded"]=true,["detail"]="Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:47",["text"]="Doctor Draxlegauge",["superseded"]=true},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:48",["text"]="The Drowned Reef: kill these as you meet them",["superseded"]=true,["detail"]="The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:49",["text"]="Faldir's Cove",["superseded"]=true},{["goals"]={{["map"]=1417,["itemName"]="Trelane's Wand of Invocation",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=2793,["t"]="collect",["id"]="solo:forever/alliance/30-40/05-arathi-highlands:46:1",["fromKind"]="npc",["y"]=0.8187000000000001,["x"]=0.5475,["title"]="Wand over Fist",["from"]="Kor'gresh Coldrage",["item"]=4525,["note"]="Trelane's Wand of Invocation; below ground",["quest"]=693,["count"]=1}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:46",["text"]="Kor'gresh Coldrage",["detail"]="South-east through the hills: Kor'gresh Coldrage, an ogre mage, holds the cave at the southern end of the Witherbark valley.\nCareful: Kor'gresh Coldrage is level 39, a caster, one or two over you here: clear the cave mouth first, then pull him alone at full health."},{["goals"]={{["map"]=1417,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:47:1",["t"]="accept",["npc"]=2696,["y"]=0.9264,["x"]=0.4324,["title"]="MacKreel's Moonshine",["minLevel"]=28,["limit"]=900,["qlvl"]=30,["quest"]=647,["npcName"]="Foggy MacKreel"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:47",["text"]="Foggy MacKreel",["detail"]="South-west from Kor'gresh Coldrage's cave to the Thandol Span: Foggy MacKreel stands on a broken section of the bridge; jump down to him from its north end. MacKreel's Moonshine must reach Brewmeister Bilger in Southshore within 15 minutes: go straight back to Refuge Pointe and fly to Southshore."},{["id"]="solo:forever/alliance/30-40/05-arathi-highlands:48",["text"]="Skuerto",["goals"]={{["map"]=1417,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:48:1",["t"]="turnin",["npc"]=2789,["npcName"]="Skuerto",["x"]=0.46649999999999997,["title"]="Wand over Fist",["quest"]=693,["y"]=0.47009999999999996}},["soloSpeedrun"]=true},{["id"]="solo:forever/alliance/30-40/05-arathi-highlands:49",["text"]="Fly to Southshore",["goals"]={{["map"]=1417,["x"]=0.45799999999999996,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:49:1",["text"]="Refuge Pointe flight master",["y"]=0.461,["t"]="goto"},{["id"]="solo:forever/alliance/30-40/05-arathi-highlands:49:2",["soloSpeedrun"]=true,["location"]="Southshore",["t"]="fly",["node"]=14,["area"]=271}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1424,["note"]="Brewmeister Bilger, below ground",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:50:1",["t"]="turnin",["npc"]=2705,["npcName"]="Brewmeister Bilger",["x"]=0.5213,["title"]="MacKreel's Moonshine",["quest"]=647,["y"]=0.5874},{["map"]=1424,["note"]="Magistrate Henry Maleb, inside",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:54:2",["t"]="turnin",["npc"]=2276,["npcName"]="Magistrate Henry Maleb",["x"]=0.4814,["title"]="Syndicate Assassins",["quest"]=505,["y"]=0.5911},{["map"]=1424,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:54:3",["t"]="turnin",["npc"]=2276,["npcName"]="Magistrate Henry Maleb",["x"]=0.4814,["title"]="Foreboding Plans",["quest"]=510,["y"]=0.5911},{["map"]=1424,["note"]="Magistrate Henry Maleb: the signet rings are in Strahnbrad",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:54:4",["t"]="accept",["npc"]=2276,["y"]=0.5911,["x"]=0.4814,["title"]="Noble Deaths",["minLevel"]=26,["pre"]={510},["qlvl"]=36,["quest"]=512,["npcName"]="Magistrate Henry Maleb"},{["map"]=1424,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:54:5",["t"]="turnin",["npc"]=2277,["npcName"]="Loremaster Dibbs",["x"]=0.5057,["title"]="Encrypted Letter",["quest"]=511,["y"]=0.5709000000000001},{["map"]=1424,["note"]="For Prospector Stormpike in Ironforge, at the end of this guide",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:54:6",["t"]="accept",["npc"]=2277,["y"]=0.5709000000000001,["x"]=0.5057,["title"]="Letter to Stormpike",["minLevel"]=30,["pre"]={511},["qlvl"]=34,["quest"]=514,["npcName"]="Loremaster Dibbs"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:54",["text"]="Brewmeister Bilger",["detail"]="Off the flight, straight to the Southshore inn. Then Magistrate Henry Maleb and Loremaster Dibbs, in the town hall, take the Syndicate camp's quests and send you north to Strahnbrad."},{["id"]="solo:forever/alliance/30-40/05-arathi-highlands:51",["text"]="Alterac Mountains",["goals"]={{["map"]=1416,["x"]=0.45,["y"]=0.772,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:51:1",["t"]="goto",["text"]="Gavin's Naze",["area"]=1677}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1416,["oi"]=2,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:52:1",["t"]="kill",["npc"]=2407,["y"]=0.767,["x"]=0.442,["title"]="Costly Menace",["lvl"]=34,["target"]="Hulking Mountain Lion",["quest"]=564,["count"]=10},{["map"]=1416,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:56:2",["t"]="kill",["npc"]=2406,["y"]=0.828,["x"]=0.321,["title"]="Costly Menace",["target"]="Mountain Lion",["quest"]=564,["count"]=8}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:56",["text"]="Gavin's Naze",["detail"]="Follow the road north out of Southshore into the mountains. Mountain lions roam the slopes; the Syndicate in Strahnbrad wear the signet rings."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:57",["text"]="Ruins of Alterac: kill these as you meet them",["superseded"]=true,["detail"]="The tomes lie in the ruined keep west of Strahnbrad; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and carry the tomes too: pull one at a time, or group up."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:58",["text"]="Ruins of Alterac: kill these as you meet them",["superseded"]=true,["detail"]="These are elite mobs: grouping up is encouraged, look for people to do it with. Grel'borg the Miser is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nGrel'borg the Miser walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."},{["goals"]={{["itemName"]="Alterac Signet Ring",["item"]=3505,["quest"]=512,["fromId"]=2242,["map"]=1416,["fromNpcsAt"]="5;3,4;3,4;3,4;3;3,4;3;2,6,7;6,2;2,6;2;1,5;3;3;6",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:59:1",["fromAlso"]="Syndicate Sentry",["title"]="Noble Deaths",["from"]="Syndicate Spy",["y"]=0.16440000000000002,["x"]=0.4008,["count"]=7,["lvl"]=36,["spread"]=true,["t"]="collect",["fromKind"]="npc",["fromAlsoId"]=2243}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:59",["text"]="Strahnbrad: kill these as you meet them",["detail"]="Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: Baron Vardus (40) turns up in one spot at a time: the cellar of Strahnbrad's inn, or one of the Syndicate tent camps north of the village. Leave him be."},{["goals"]={{["map"]=1416,["itemName"]="Dirty Knucklebones",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:60:1",["t"]="collect",["y"]=0.3059,["x"]=0.4153,["title"]="Crushridge Bounty",["lvl"]=36,["item"]=2843,["quest"]=500,["spread"]=true,["count"]=9}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:60",["text"]="Crushridge ogres",["detail"]="The Crushridge ogres hold the hills north of Strahnbrad. Careful: Nagaz (40) stands far to the north-west by a worn wooden chest, with Syndicate guards: stay with the ogres.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up."},{["id"]="solo:forever/alliance/30-40/05-arathi-highlands:57",["text"]="Silverpine Forest",["goals"]={{["map"]=1421,["x"]=0.6859999999999999,["y"]=0.452,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:57:1",["t"]="goto",["text"]="Dalaran",["area"]=279}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1421,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:58:1",["t"]="turnin",["npc"]=269127,["npcName"]="Image of Archmage Modera",["x"]=0.6862,["title"]="An Alarming Request",["quest"]=92432,["y"]=0.4518},{["map"]=1416,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:58:2",["t"]="turnin",["npc"]=2543,["npcName"]="Archmage Ansirem Runeweaver",["x"]=0.1416,["title"]="Magical Analysis",["quest"]=602,["y"]=0.5972999999999999},{["map"]=1416,["note"]="For Catelyn the Blade in Booty Bay: keep it",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:58:3",["t"]="accept",["npc"]=2543,["y"]=0.5972999999999999,["x"]=0.1416,["title"]="Ansirem's Key",["minLevel"]=32,["pre"]={602},["qlvl"]=37,["quest"]=603,["npcName"]="Archmage Ansirem Runeweaver"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:58",["text"]="Dalaran",["detail"]="South-west to the Kirin Tor camp on the lake shore west of Dalaran, just over the border into Silverpine Forest: the Image of Archmage Modera stands there. Archmage Ansirem stands south-east of it, by the dome."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:63",["text"]="Image of Archmage Modera",["superseded"]=true,["detail"]="For your City of Dalaran run, next: the Image of Archmage Modera wants the arcane remnants in the city thinned out and a mote from the heart of the disruption. Heart of Disruption brings the Dalaran Sewer Key, which opens the grate."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:64",["text"]="City of Dalaran",["superseded"]=true,["detail"]="The City of Dalaran is a dungeon for a group of five at about level 28 to 33: at your level it goes quickly. Its way in is the sewer grate in the city's western wall, by the lake, 30 yards from Modera's camp.\nInside: the Seeking Remnants, Saturated Remnants and Mana Echoes are Modera's Starving Arcane; the Arcane Mote for Heart of Disruption drops inside too."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:65",["text"]="Image of Archmage Modera",["superseded"]=true,["detail"]="Back out of the grate to Modera's camp on the lake shore."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:66",["text"]="Image of Archmage Modera",["superseded"]=true},{["id"]="solo:forever/alliance/30-40/05-arathi-highlands:59",["text"]="Hillsbrad Foothills",["goals"]={{["map"]=1424,["x"]=0.48100000000000004,["y"]=0.591,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:59:1",["t"]="goto",["text"]="Southshore",["area"]=271}},["soloSpeedrun"]=true},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:68",["text"]="Southshore",["goals"]={{["map"]=1424,["note"]="Magistrate Henry Maleb, inside",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:60:2",["t"]="turnin",["npc"]=2276,["npcName"]="Magistrate Henry Maleb",["x"]=0.4814,["title"]="Noble Deaths",["quest"]=512,["y"]=0.5911},{["map"]=1424,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:60:4",["t"]="turnin",["npc"]=2263,["npcName"]="Marshal Redpath",["x"]=0.4947,["title"]="Crushridge Bounty",["quest"]=500,["y"]=0.5872999999999999},{["map"]=1424,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:60:5",["t"]="turnin",["npc"]=2711,["npcName"]="Phin Odelic",["x"]=0.5035000000000001,["title"]="Hints of a New Plague?",["quest"]=661,["y"]=0.5905},{["map"]=1424,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:60:10",["t"]="turnin",["npc"]=2382,["npcName"]="Darren Malvew",["x"]=0.5242,["title"]="Costly Menace",["quest"]=564,["y"]=0.5596}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1424,["itemName"]="Fine Thread",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:61:1",["t"]="buy",["npc"]=2381,["soloWhen"]={{["k"]="complete",["q"]=565}},["npcName"]="Micha Yance",["x"]=0.4894,["item"]=2321,["count"]=1,["y"]=0.5503,["optional"]=true,["note"]="Fine Thread, from Micha Yance"},{["map"]=1424,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:61:2",["t"]="turnin",["npc"]=2438,["soloWhen"]={{["k"]="complete",["q"]=565}},["npcName"]="Bartolo Ginsetti",["x"]=0.4943,["title"]="Bartolo's Yeti Fur Cloak",["quest"]=565,["y"]=0.5553}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:61",["text"]="Bartolo Ginsetti",["soloWhen"]={{["k"]="complete",["q"]=565}},["detail"]="Bartolo Ginsetti stands between the flight master and the inn; Micha Yance beside him sells Fine Thread if you have none."},{["id"]="so