",["npc"]=1572,["npcName"]="Thorgrum Borrelson",["x"]=0.3394,["location"]="Thelsamar",["y"]=0.5095000000000001,["node"]=8,["area"]=144},{["map"]=1432,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:66:2",["t"]="sethome",["npc"]=6734,["npcName"]="Innkeeper Hearthstove",["x"]=0.3553,["location"]="Stoutlager Inn",["y"]=0.484,["area"]=2101},{["map"]=1432,["note"]="Ghak Healtouch, below ground",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:66:3",["t"]="accept",["npc"]=1470,["npcName"]="Ghak Healtouch",["x"]=0.37070000000000003,["title"]="Badlands Reagent Run",["minLevel"]=36,["qlvl"]=39,["quest"]=2500,["y"]=0.4938}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1432,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/05-arathi-highlands:67:1",["t"]="turnin",["npc"]=1344,["npcName"]="Prospector Ironband",["x"]=0.6593000000000001,["title"]="Ironband Wants You!",["quest"]=707,["y"]=0.6562},{["map"]=1432,["crumbs"]={707},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:goal:75:2",["t"]="accept",["npc"]=1344,["y"]=0.6562,["x"]=0.6593000000000001,["title"]="Find Agmond",["minLevel"]=30,["qlvl"]=38,["quest"]=738,["npcName"]="Prospector Ironband"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/05-arathi-highlands:step:75",["text"]="Prospector Ironband",["detail"]="South-east along the loch to the dig site."}},["max"]=37,["soloSpeedrun"]=true,["min"]=35,["availability"]="source-listed",["name"]="Arathi Highlands, Alterac Mountains & Swamp of Sorrows (solo 35-37)",["category"]="Leveling",["zoneName"]="Arathi Highlands",["faction"]="Alliance",["refreshRevision"]="forever-20261117-b753c783",["next"]="solo:forever/alliance/30-40/06-badlands"} end},
{id="solo:forever/alliance/30-40/06-badlands",faction="Alliance",races=nil,build=function()return {["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; adapted Forever solo leveling plan",["zone"]=1418,["id"]="solo:forever/alliance/30-40/06-badlands",["steps"]={{["id"]="solo:forever/alliance/30-40/06-badlands:1",["text"]="Into Badlands",["goals"]={{["map"]=1418,["x"]=0.494,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:1:1",["text"]="Into Badlands",["y"]=0.08,["t"]="goto"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1418,["note"]="Dorgaron: keep it, the Pristine Mattock waits for the 40-50 Badlands visit",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:2:1",["t"]="accept",["npc"]=269577,["npcName"]="Dorgaron",["x"]=0.5463,["title"]="Safety Checks",["minLevel"]=35,["qlvl"]=40,["quest"]=97617,["y"]=0.12869999999999998}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:2",["text"]="Dorgaron",["detail"]="Dorgaron of the Explorers' League camps at the foot of the pass. His artifacts drop from the Shadowforge diggers at Hammertoe's Digsite and the Stonevault Bonesnappers at Agmond's End, and the helmet lies in the Shadowforge camp."},{["id"]="solo:forever/alliance/30-40/06-badlands:2",["text"]="Badlands",["goals"]={{["map"]=1418,["x"]=0.534,["y"]=0.434,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:2:1",["t"]="goto",["text"]="Hammertoe's Digsite",["area"]=346}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:3:1",["t"]="accept",["npc"]=2910,["npcName"]="Prospector Ryedol",["x"]=0.5342,["title"]="A Dwarf and His Tools",["minLevel"]=35,["qlvl"]=35,["quest"]=719,["y"]=0.4339},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:3:2",["t"]="accept",["npc"]=2860,["npcName"]="Sigrun Ironhew",["x"]=0.5379999999999999,["title"]="Mirages",["minLevel"]=35,["qlvl"]=38,["quest"]=718,["y"]=0.433}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:3",["text"]="Hammertoe's Digsite",["detail"]="Head back west to the road and follow it south out of Loch Modan through the pass into the Badlands. Prospector Ryedol and Sigrun Ironhew camp side by side at the dig."},{["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:4:1",["t"]="accept",["y"]=0.3394,["x"]=0.5303,["title"]="A Sign of Hope",["objName"]="Crumpled Map",["object"]=2868,["minLevel"]=35,["quest"]=720,["qlvl"]=35},{["itemName"]="Crag Coyote Fang",["item"]=7846,["quest"]=2500,["map"]=1418,["fromId"]=2727,["oi"]=2,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:4:2",["fromAlso"]="Feral Crag Coyote",["t"]="collect",["title"]="Badlands Reagent Run",["y"]=0.35240000000000005,["x"]=0.5015999999999999,["count"]=10,["from"]="Crag Coyote",["lvl"]=40,["spread"]=true,["fromKind"]="npc",["fromAlsoId"]=2728},{["map"]=1418,["itemName"]="Ryedol's Lucky Pick",["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:4:3",["t"]="collect",["y"]=0.34299999999999997,["x"]=0.5146999999999999,["title"]="A Dwarf and His Tools",["lvl"]=37,["item"]=4616,["quest"]=719,["count"]=1},{["map"]=1418,["itemName"]="Explorers' League Mining Helmet",["oi"]=2,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:5:4",["t"]="collect",["y"]=0.345,["x"]=0.531,["title"]="Safety Checks",["item"]=278403,["note"]="Explorers' League Mining Helmet, in the Shadowforge camp",["count"]=1,["quest"]=97617,["carriedTo"]="forever/alliance/40-50/02-badlands"},{["map"]=1418,["itemName"]="Buzzard Gizzard",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:5:5",["fromNpcsAt"]="1;;1;1;1;1;;;;2;2;",["y"]=0.28600000000000003,["x"]=0.575,["title"]="Badlands Reagent Run",["item"]=7847,["note"]="Buzzard Gizzard: the Starving Buzzards (35-37) circling the hills north of the digsite drop it most often; leave the Giant Buzzards (39-41) of the far west",["count"]=5,["quest"]=2500,["t"]="collect"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:5",["text"]="Hammertoe's Digsite: kill these as you meet them",["detail"]="The Shadowforge dwarves camp just north of the digsite; the crumpled map and Dorgaron's mining helmet lie among their tents. Tunnelers and Darkweavers carry Ryedol's pick and Dorgaron's artifacts. Crag Coyotes roam the slopes around it."},{["goals"]={{["map"]=1418,["itemName"]="Supply Crate",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=2867,["t"]="collect",["id"]="solo:forever/alliance/30-40/06-badlands:5:1",["y"]=0.22,["x"]=0.6659999999999999,["count"]=1,["from"]="Excavation Supply Crate",["quest"]=718,["item"]=4629,["fromKind"]="object",["title"]="Mirages"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:5",["text"]="The excavation crate",["detail"]="Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."},{["id"]="solo:forever/alliance/30-40/06-badlands:6",["text"]="Hammertoe's Digsite",["goals"]={{["id"]="solo:forever/alliance/30-40/06-badlands:6:1",["text"]="Ryedol's next errand goes into Uldaman: skip it.",["t"]="note",["soloSpeedrun"]=true},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:6:2",["t"]="turnin",["npc"]=2860,["npcName"]="Sigrun Ironhew",["x"]=0.5379999999999999,["title"]="Mirages",["quest"]=718,["y"]=0.433},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:6:3",["t"]="accept",["npc"]=2860,["y"]=0.433,["x"]=0.5379999999999999,["title"]="Scrounging",["minLevel"]=35,["pre"]={718},["qlvl"]=40,["quest"]=733,["npcName"]="Sigrun Ironhew"},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:6:4",["t"]="turnin",["npc"]=2910,["npcName"]="Prospector Ryedol",["x"]=0.5342,["title"]="A Sign of Hope",["quest"]=720,["y"]=0.4339},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:6:5",["t"]="turnin",["npc"]=2910,["npcName"]="Prospector Ryedol",["x"]=0.5342,["title"]="A Dwarf and His Tools",["quest"]=719,["y"]=0.4339}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:7:1",["t"]="turnin",["npc"]=4618,["npcName"]="Martek the Exiled",["x"]=0.42219999999999996,["title"]="Martek the Exiled",["quest"]=1106,["y"]=0.5268999999999999},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:7:2",["t"]="accept",["npc"]=4618,["y"]=0.5268999999999999,["x"]=0.42219999999999996,["title"]="Indurium",["minLevel"]=28,["pre"]={1106},["qlvl"]=39,["quest"]=1108,["npcName"]="Martek the Exiled"},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:7:3",["t"]="accept",["npc"]=2817,["npcName"]="Rigglefuzz",["x"]=0.4239,["title"]="Barbecued Buzzard Wings",["minLevel"]=33,["qlvl"]=40,["quest"]=703,["y"]=0.5293},{["map"]=1418,["note"]="The clams lie on Stranglethorn's north-west coast, in the next guide: keep it",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:7:4",["t"]="accept",["npc"]=2817,["npcName"]="Rigglefuzz",["x"]=0.4239,["title"]="Pearl Diving",["minLevel"]=30,["qlvl"]=37,["quest"]=705,["y"]=0.5293}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:7",["text"]="Valley of Fangs",["detail"]="Martek the Exiled and Rigglefuzz camp together in the Valley of Fangs, in the middle of the Badlands."},{["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:8:1",["t"]="turnin",["y"]=0.624,["x"]=0.5089,["title"]="Find Agmond",["objName"]="Battered Dwarven Skeleton",["quest"]=738,["object"]=2875}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:8",["text"]="Agmond's End",["detail"]="The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."},{["goals"]={{["map"]=1418,["itemName"]="Buzzard Wing",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:10:1",["t"]="collect",["y"]=0.6385000000000001,["x"]=0.5525,["title"]="Barbecued Buzzard Wings",["item"]=3404,["quest"]=703,["spread"]=true,["count"]=4},{["map"]=1418,["itemName"]="Buzzard Gizzard",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:10:2",["fromNpcsAt"]=";;2;2;;;1;1;",["title"]="Badlands Reagent Run",["y"]=0.6,["x"]=0.5,["item"]=7847,["quest"]=2500,["count"]=5,["note"]="Buzzard Gizzard, if you still need one: the Buzzards east of Agmond's End drop it only rarely",["spread"]=true,["t"]="collect"},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:9:4",["t"]="accept",["qlvl"]=42,["y"]=0.624,["x"]=0.5089,["title"]="Murdaloc",["objName"]="Battered Dwarven Skeleton",["pre"]={738},["minLevel"]=30,["quest"]=739,["object"]=2875},{["id"]="solo:forever/alliance/30-40/06-badlands:9:5",["text"]="Murdaloc himself (42) walks among the Bonesnappers: leave him for the later Badlands guide at 43, and kill the Bonesnappers for this quest now.",["t"]="note",["soloSpeedrun"]=true},{["itemName"]="Indurium Flake",["item"]=5797,["quest"]=1108,["map"]=1418,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=2893,["t"]="collect",["id"]="solo:forever/alliance/30-40/06-badlands:9:6",["count"]=10,["y"]=0.6436,["x"]=0.5092,["title"]="Indurium",["lvl"]=41,["fromAlso"]="Stonevault Shaman",["from"]="Stonevault Bonesnapper",["fromKind"]="npc",["fromAlsoId"]=2894},{["map"]=1418,["oi"]=2,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:10:6",["t"]="kill",["npc"]=2893,["y"]=0.6436,["x"]=0.5092,["carriedTo"]="forever/alliance/40-50/02-badlands",["lvl"]=40,["target"]="Stonevault Bonesnapper",["count"]=12,["quest"]=739,["title"]="Murdaloc"},{["map"]=1418,["itemName"]="Unstudied Artifact",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:10:7",["t"]="collect",["item"]=278402,["spread"]=true,["y"]=0.6436,["x"]=0.5092,["carriedTo"]="forever/alliance/40-50/02-badlands",["lvl"]=41,["note"]="Unstudied Artifact, from the Shadowforge diggers and the Bonesnappers",["title"]="Safety Checks",["quest"]=97617,["count"]=8}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:10",["text"]="Agmond's End: kill these as you meet them",["detail"]="Buzzards circle the plain to the east. Careful: the Dustbelcher Maulers, Shamans and Wyrmhunters (40-43) camp far to the south-west: leave them.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; Murdaloc, Agmond's killer, walks among the Bonesnappers.\nCareful: the Stonevault Bonesnappers are 39-40 and the Shamans 40-41, a level or two over you here: pull them from the camp's edge, one at a time.\nCareful: Dustbelcher Lords are level 44-45. They use Battle Shout and Demoralizing Shout, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of Kargath."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:11",["text"]="Theldurin the Lost",["superseded"]=true,["detail"]="Theldurin sits by the ruined camp south of the trogg camp. His tablet lies just inside Uldaman's cave mouth, beside level 38 elites: a quest for a group."},{["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:10:1",["t"]="accept",["npc"]=2921,["npcName"]="Lotwil Veriatus",["x"]=0.2595,["title"]="Study of the Elements: Rock",["minLevel"]=35,["qlvl"]=37,["quest"]=710,["y"]=0.4487}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:10",["text"]="Lotwil Veriatus",["detail"]="Head west into the Dustbowl; Lotwil Veriatus works by his machines in the middle of it."},{["goals"]={{["map"]=1418,["itemName"]="Small Stone Shard",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=2735,["t"]="collect",["id"]="solo:forever/alliance/30-40/06-badlands:11:1",["fromKind"]="npc",["y"]=0.4547,["x"]=0.2353,["title"]="Study of the Elements: Rock",["lvl"]=39,["item"]=4626,["from"]="Lesser Rock Elemental",["quest"]=710,["count"]=10},{["map"]=1418,["itemName"]="Rock Elemental Shard",["oi"]=3,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:13:2",["t"]="collect",["item"]=7848,["y"]=0.4547,["x"]=0.2353,["title"]="Badlands Reagent Run",["lvl"]=40,["spread"]=true,["fromNpcsAt"]="1;1;4,1;6;4;4;4;4;4;3;2;2;2,5;1;2,5;2,5;2,5",["quest"]=2500,["count"]=5},{["map"]=1418,["itemName"]="Scrap Metal",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:13:3",["fromNpcsAt"]="2,1;2,1;3,4",["title"]="Scrounging",["y"]=0.593,["x"]=0.295,["item"]=4630,["lvl"]=40,["note"]="Scrap Metal, from the Dustbelcher Ogres",["count"]=7,["quest"]=733,["t"]="collect"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:13",["text"]="Lesser Rock Elementals",["detail"]="The Lesser Rock Elementals wander the Dustbowl west of Lotwil Veriatus; every rock elemental can drop Ghak Healtouch's Rock Elemental Shards. The Dustbelcher Ogres (38-39) on the Dustbowl's west side drop Sigrun Ironhew's scrap. Careful: a Malevolent Mirage, a level 42 elite, drifts about the Dustbowl: give it a wide berth.\nCareful: the Lesser Rock Elementals are 37-39 and hit hard: fight them one at a time."},{["id"]="solo:forever/alliance/30-40/06-badlands:12",["text"]="Lotwil Veriatus",["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:12:1",["t"]="turnin",["npc"]=2921,["npcName"]="Lotwil Veriatus",["x"]=0.2595,["title"]="Study of the Elements: Rock",["quest"]=710,["y"]=0.4487},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:12:2",["t"]="accept",["npc"]=2921,["y"]=0.4487,["x"]=0.2595,["title"]="Study of the Elements: Rock",["minLevel"]=35,["pre"]={710},["qlvl"]=39,["quest"]=711,["npcName"]="Lotwil Veriatus"}},["soloSpeedrun"]=true},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:15",["text"]="The Ancient Chest",["superseded"]=true,["detail"]="Head north to Uldaman's entrance, in the north of the Badlands: the chest lies just inside the cave mouth. Magregan Deepshadow and the Obsidian Golems (38) stand beside it and Shadowforge Diggers (35-36) work the tunnel, all elite: keep your group together."},{["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:14:1",["t"]="turnin",["npc"]=4618,["npcName"]="Martek the Exiled",["x"]=0.42219999999999996,["title"]="Indurium",["quest"]=1108,["y"]=0.5268999999999999},{["map"]=1418,["note"]="For Fizzle Brassbolts at the Mirage Raceway: the Tanaris guide passes him at 45, keep it",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:14:2",["t"]="accept",["npc"]=4618,["y"]=0.5268999999999999,["x"]=0.42219999999999996,["title"]="News for Fizzle",["minLevel"]=28,["pre"]={1108},["qlvl"]=38,["quest"]=1137,["npcName"]="Martek the Exiled"},{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:14:3",["t"]="turnin",["npc"]=2817,["npcName"]="Rigglefuzz",["x"]=0.4239,["title"]="Barbecued Buzzard Wings",["quest"]=703,["y"]=0.5293}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:14",["text"]="Valley of Fangs",["detail"]="Martek the Exiled and Rigglefuzz camp in the Valley of Fangs, on the road between Uldaman and Agmond's End."},{["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:goal:17:1",["t"]="turnin",["npc"]=2860,["npcName"]="Sigrun Ironhew",["x"]=0.5379999999999999,["title"]="Scrounging",["quest"]=733,["y"]=0.433}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:17",["text"]="Sigrun Ironhew",["detail"]="East from the Valley of Fangs to Hammertoe's Digsite: Sigrun Ironhew takes the scrap metal."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:18",["text"]="Theldurin the Lost",["superseded"]=true,["detail"]="Head south to Agmond's End."},{["goals"]={{["itemName"]="Large Stone Slab",["item"]=4627,["quest"]=711,["map"]=1418,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=92,["t"]="collect",["id"]="solo:forever/alliance/30-40/06-badlands:16:1",["y"]=0.7764,["x"]=0.461,["title"]="Study of the Elements: Rock",["from"]="Rock Elemental",["count"]=3,["lvl"]=40,["fromKind"]="npc",["spread"]=true}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:16",["text"]="Rock Elementals",["detail"]="The Rock Elementals roam south-east of Lotwil Veriatus; Giant Buzzards and Elder Crag Coyotes share the plain to their west. Careful: a Malevolent Mirage, a level 42 elite, drifts about the Dustbowl: give it a wide berth."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06-badlands:step:20",["text"]="Lotwil Veriatus",["goals"]={{["map"]=1418,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:17:1",["t"]="turnin",["npc"]=2921,["npcName"]="Lotwil Veriatus",["x"]=0.2595,["title"]="Study of the Elements: Rock",["quest"]=711,["y"]=0.4487}},["soloSpeedrun"]=true},{["id"]="solo:forever/alliance/30-40/06-badlands:21",["text"]="To Stoutlager Inn",["goals"]={{["map"]=1432,["x"]=0.355,["y"]=0.484,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:21:1",["t"]="goto",["text"]="Stoutlager Inn",["area"]=2101}},["soloSpeedrun"]=true},{["id"]="solo:forever/alliance/30-40/06-badlands:22",["text"]="Thelsamar",["goals"]={{["map"]=1432,["note"]="Ghak Healtouch, in the inn; below ground",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/30-40/06-badlands:22:1",["t"]="turnin",["npc"]=1470,["npcName"]="Ghak Healtouch",["x"]=0.37070000000000003,["title"]="Badlands Reagent Run",["quest"]=2500,["y"]=0.4938}},["soloSpeedrun"]=true}},["max"]=38,["soloSpeedrun"]=true,["min"]=37,["availability"]="source-listed",["name"]="Badlands (solo 37-38)",["category"]="Leveling",["zoneName"]="Badlands",["faction"]="Alliance",["refreshRevision"]="forever-20261117-b753c783",["next"]="solo:forever/alliance/30-40/06b-desolace"} end},
{id="solo:forever/alliance/30-40/06b-desolace",faction="Alliance",races=nil,build=function()return {["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; adapted Forever solo leveling plan",["zone"]=1443,["id"]="solo:forever/alliance/30-40/06b-desolace",["steps"]={{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:1",["text"]="Fly to Menethil Harbor",["goals"]={{["map"]=1432,["x"]=0.33899999999999997,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:1:1",["text"]="Thelsamar flight master",["y"]=0.508,["t"]="goto"},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:1:2",["soloSpeedrun"]=true,["location"]="Menethil Harbor",["t"]="fly",["node"]=7,["area"]=150}},["soloSpeedrun"]=true},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:2",["text"]="Boat to Theramore",["goals"]={{["map"]=1437,["x"]=0.0513,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:2:1",["text"]="Boat to Theramore",["y"]=0.6361,["t"]="goto"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1445,["x"]=0.675,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:3:1",["text"]="Theramore flight master",["y"]=0.513,["t"]="goto"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:3",["text"]="Theramore flight master",["detail"]="Off the boat, walk up the pier to Baldruc, the flight master by the gate of Foothold Citadel."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:4",["text"]="Nijel's Point",["goals"]={{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:4:1",["soloSpeedrun"]=true,["location"]="Nijel's Point",["t"]="fly",["node"]=37,["area"]=608},{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:4:2",["t"]="sethome",["npc"]=11103,["npcName"]="Innkeeper Lyshaerya",["x"]=0.6627,["location"]="Nijel's Point",["y"]=0.0655,["area"]=608},{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:4:3",["t"]="turnin",["npc"]=1182,["npcName"]="Brother Anton",["x"]=0.6652,["title"]="Brother Anton",["quest"]=6141,["y"]=0.0791},{["map"]=1443,["crumbs"]={6141},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:4:4",["t"]="accept",["npc"]=1182,["y"]=0.0791,["x"]=0.6652,["title"]="Down the Scarlet Path",["minLevel"]=34,["qlvl"]=39,["quest"]=261,["npcName"]="Brother Anton"},{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:4:5",["t"]="accept",["npc"]=5638,["y"]=0.09630000000000001,["x"]=0.662,["title"]="Reagents for Reclaimers Inc.",["minLevel"]=30,["pre"]={1459},["qlvl"]=40,["quest"]=1466,["npcName"]="Kreldig Ungor"},{["map"]=1443,["note"]="Kreldig Ungor, if 30-40/02 didn't take it: the wreck lies below Azore Aldamort's tower",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:4:6",["t"]="accept",["npc"]=5638,["y"]=0.09630000000000001,["x"]=0.662,["title"]="The Karnitol Shipwreck",["minLevel"]=30,["pre"]={1453},["qlvl"]=39,["quest"]=1454,["npcName"]="Kreldig Ungor"},{["map"]=1443,["note"]="Captain Pentigast, if 30-40/02 didn't give it",["endNpcs"]={5396},["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:4:7",["t"]="accept",["npc"]=5396,["soloSpeedrun"]=true,["npcName"]="Captain Pentigast",["x"]=0.6666,["qlvl"]=40,["minLevel"]=30,["y"]=0.1093,["title"]="Carved Centaur Totems",["quest"]=93224,["xp"]=2350}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:5:1",["t"]="accept",["npc"]=11438,["npcName"]="Bibbly F'utzbuckle",["x"]=0.6233,["title"]="Bone Collector",["minLevel"]=33,["qlvl"]=39,["quest"]=5501,["y"]=0.3899}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:5",["text"]="Bibbly F'utzbuckle",["detail"]="Follow the road south to Kormek's Hut."},{["goals"]={{["map"]=1443,["itemName"]="Kodo Bone",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=176751,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:6:1",["y"]=0.5811999999999999,["x"]=0.5389,["count"]=10,["from"]="Kodo Bones",["quest"]=5501,["item"]=13703,["fromKind"]="object",["title"]="Bone Collector"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:6",["text"]="Kodo Graveyard",["detail"]="Hornizz Brimbuzzle stands at the edge of the Kodo Graveyard, south-west of Kormek's Hut; Kodo Bones lie among the skeletons."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:7",["text"]="Hornizz Brimbuzzle",["superseded"]=true,["detail"]="These are elite mobs: grouping up is encouraged, look for people to do it with. Ghost-o-plasm Round Up's magnets draw the Magrami Spectres a few yards from the Magram Necrokhans and Corpsefeeders (45, elite) in the Valley of Bones. Skip it if you are alone."},{["goals"]={{["map"]=1443,["itemName"]="Flesh Picker Specimen",["soloSpeedrun"]=true,["fromId"]=217590,["t"]="collect",["soloWhen"]={{["k"]="onquest",["q"]={93176}}},["y"]=0.5710000000000001,["x"]=0.48100000000000004,["item"]=213567,["lvl"]=1,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:8:1",["fromKind"]="npc",["from"]="Flesh Picker"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:8",["text"]="Flesh Picker",["soloWhen"]={{["k"]="onquest",["q"]={93176}}},["detail"]="A Flesh Picker crawls about the Kodo Graveyard: catch one with the tool from Amaryllis Webb's Entomology Starter Kit."},{["goals"]={{["map"]=1443,["itemName"]="Carved Centaur Totem",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:9:1",["t"]="collect",["item"]=254432,["y"]=0.6141,["x"]=0.3971,["title"]="Carved Centaur Totems",["lvl"]=41,["spread"]=true,["fromNpcsAt"]="1;1,18;1,15;15,18,13,1;15,13,28,32;1,18;7,17,9,8,12;8,20,9,12,21;6,10,11,14;23,22;22;11;16,5,26;4,3,16,26;16,4,5;3,5,2;2,3;2,3,5;1,18;18;18;13,15,1;18,1;1,18,13,29;15,13,29;13,18,15,28;15,13,28;7,8,9,12;17,8,19;7,19,9,8;9,8;7,9,8,19,17,12;7,19,17,8,9;12,19,17,9,8;7,9,8,19,12;9,12,8,7;8,9,21,20,7;9,20,8,12,21;8,9,12,21;6,11,10,14,27;10,23,11,6;6,22,11,23,10,14;2,3,30,31;6,24,10,11,14,25;11,22;10,14,6,11,27;3,2,30,31;6,14,25,10,11;6,14,10,27,24,25;6,24;16,3,4,5,26;6,11,10;10,22,23;24,6,10,11,25;6,10,11,14,27,25;11,10;16,4,5,26;4,5;10",["quest"]=93224,["count"]=5}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:9",["text"]="Maraudine centaurs",["detail"]="The Maraudine centaurs hold the Valley of Spears west of the graveyard; every kind drops the totems."},{["goals"]={{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:10:1",["t"]="accept",["npc"]=12277,["npcName"]="Melizza Brimbuzzle",["x"]=0.3395,["escort"]=true,["minLevel"]=34,["y"]=0.535,["qlvl"]=39,["quest"]=6132,["title"]="Get Me Out of Here!"},{["map"]=1443,["note"]="escort Melizza Brimbuzzle back toward the graveyard",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:10:2",["t"]="complete",["objs"]={{["count"]=1,["text"]="Melizza Brimbuzzle escorted to safety"}},["y"]=0.616,["x"]=0.401,["title"]="Get Me Out of Here!",["quest"]=6132,["escort"]=true}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:10",["text"]="Melizza Brimbuzzle",["detail"]="Melizza Brimbuzzle is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."},{["goals"]={{["itemName"]="Nether Wing",["item"]=6251,["quest"]=1466,["map"]=1443,["oi"]=2,["soloSpeedrun"]=true,["fromId"]=4679,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:11:1",["count"]=10,["y"]=0.743,["x"]=0.505,["title"]="Reagents for Reclaimers Inc.",["from"]="Nether Maiden",["fromAlso"]="Nether Sister",["note"]="Nether Wing, from the Nether Maidens",["fromKind"]="npc",["fromAlsoId"]=4682},{["itemName"]="Doomwarder Blood",["item"]=6252,["quest"]=1466,["map"]=1443,["fromId"]=4680,["oi"]=3,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:11:2",["fromAlso"]="Kaskk",["t"]="collect",["title"]="Reagents for Reclaimers Inc.",["y"]=0.8340000000000001,["x"]=0.517,["count"]=10,["from"]="Doomwarder Captain",["note"]="Doomwarder Blood, from the Doomwarder Captains",["lvl"]=38,["fromKind"]="npc",["fromAlsoId"]=14226}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:11",["text"]="Mannoroc Coven",["detail"]="The demons gather at the Mannoroc Coven in southern Desolace. Nether Maidens (37-38) hold its north-west side and drop the wings; Doomwarder Captains (38) stand at the south end and drop the blood.\nCareful: Nether Sorceresses (39-40) stand beside the Doomwarder Captains, and Lord Azrethoc, a level 40 elite, walks the coven's middle: pull the captains away from them. Most of the mobs here walk patrol routes, so you can easily pull extra mobs."},{["goals"]={{["map"]=1443,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:12:1",["t"]="kill",["npc"]=11561,["y"]=0.909,["x"]=0.611,["title"]="Down the Scarlet Path",["target"]="Undead Ravager",["quest"]=261,["count"]=30}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:12",["text"]="The Valley of Bones",["detail"]="Undead Ravagers roam the bone fields south of the Magram village, east of the Coven: the arrow leads to their western edge. Careful: Magram Necrokhans and Corpsefeeders (45, elite) walk the bone fields further east, with Magram Necromancers (42): pull the Ravagers to you, away from them."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:13",["text"]="The ghost magnets",["superseded"]=true,["detail"]="Use the Crate of Ghost Magnets at its arrow, on the fields' eastern side, to draw the Magrami Spectres; the Necrokhans and Corpsefeeders (45, elite) walk close by: keep the group together."},{["goals"]={{["itemName"]="Felhound Brain",["item"]=6250,["quest"]=1466,["map"]=1443,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=4678,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:14:1",["count"]=10,["y"]=0.6809999999999999,["x"]=0.522,["title"]="Reagents for Reclaimers Inc.",["lvl"]=39,["fromAlso"]="Mage Hunter",["from"]="Mana Eater",["fromKind"]="npc",["fromAlsoId"]=4681}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:14",["text"]="Mannoroc Coven",["detail"]="Back at the coven on the way west: the Mana Eaters (37-38) on its north edge and the Mage Hunters (38-39) further in drop the brains. Lord Azrethoc (40, elite) walks among the Mage Hunters: pull them out to you."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:15",["text"]="Hornizz Brimbuzzle",["goals"]={{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:15:1",["t"]="turnin",["npc"]=6019,["npcName"]="Hornizz Brimbuzzle",["x"]=0.4783,["title"]="Get Me Out of Here!",["quest"]=6132,["y"]=0.6183}},["soloSpeedrun"]=true},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:16",["text"]="Hornizz Brimbuzzle",["superseded"]=true},{["goals"]={{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:17:1",["t"]="turnin",["npc"]=11863,["npcName"]="Azore Aldamort",["x"]=0.38880000000000003,["title"]="Sceptre of Light",["quest"]=5741,["y"]=0.2716},{["map"]=1443,["note"]="Azore Aldamort: The Visiting Mage, from Magtoor in the Swamp of Sorrows",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:17:2",["t"]="turnin",["npc"]=11863,["npcName"]="Azore Aldamort",["x"]=0.38880000000000003,["title"]="The Visiting Mage",["quest"]=93464,["y"]=0.2716},{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:17:3",["t"]="accept",["npc"]=11863,["y"]=0.2716,["x"]=0.38880000000000003,["title"]="Book of the Ancients",["minLevel"]=30,["pre"]={5741},["qlvl"]=38,["quest"]=6027,["npcName"]="Azore Aldamort"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:17",["text"]="Azore Aldamort",["detail"]="Follow the road west across the north of Desolace to the ruins of Ethel Rethor. Azore Aldamort's tower stands on the hill there, on the way to the wreck."},{["goals"]={{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:18:1",["t"]="turnin",["y"]=0.3045,["x"]=0.3611,["title"]="The Karnitol Shipwreck",["objName"]="Karnitol's Chest",["quest"]=1454,["object"]=35251},{["map"]=1443,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:18:2",["t"]="accept",["qlvl"]=39,["y"]=0.3045,["x"]=0.3611,["title"]="The Karnitol Shipwreck",["objName"]="Karnitol's Chest",["pre"]={1454},["minLevel"]=30,["quest"]=1455,["object"]=35251}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:18",["text"]="Karnitol's Chest",["detail"]="The wrecked ship's chest lies just south-west of Azore Aldamort's tower."},{["goals"]={{["map"]=1443,["note"]="Rackmore's Log, if 30-40/02 didn't take it",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:19:1",["t"]="accept",["y"]=0.3041,["x"]=0.3607,["title"]="Claim Rackmore's Treasure!",["objName"]="Rackmore's Log",["object"]=177787,["minLevel"]=30,["quest"]=6161,["qlvl"]=36},{["itemName"]="Rackmore's Silver Key",["item"]=15878,["quest"]=6161,["map"]=1443,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=11562,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:19:2",["count"]=1,["y"]=0.335,["x"]=0.34700000000000003,["title"]="Claim Rackmore's Treasure!",["from"]="Drysnap Crawler",["fromAlso"]="Drysnap Pincer",["note"]="Underwater",["fromKind"]="npc",["fromAlsoId"]=11563}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:19",["text"]="Claim Rackmore's Treasure!",["detail"]="Rackmore's Log lies beside Karnitol's Chest, if you didn't take it on your first Desolace visit. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."},{["goals"]={{["itemName"]="Karnitol's Satchel",["item"]=6245,["quest"]=1456,["map"]=1443,["fromId"]=4716,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:20:1",["fromAlso"]="Slitherblade Sea Witch",["t"]="collect",["title"]="The Karnitol Shipwreck",["y"]=0.105,["x"]=0.332,["count"]=1,["from"]="Slitherblade Tidehunter",["note"]="Underwater",["lvl"]=37,["fromKind"]="npc",["fromAlsoId"]=4719},{["itemName"]="Rackmore's Golden Key",["item"]=15881,["fromRank"]=4,["quest"]=6161,["map"]=1443,["oi"]=2,["soloSpeedrun"]=true,["fromId"]=14229,["t"]="collect",["y"]=0.077,["x"]=0.27899999999999997,["title"]="Claim Rackmore's Treasure!",["from"]="Accursed Slitherblade",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:20:2",["count"]=1,["fromKind"]="npc",["note"]="Rackmore's Golden Key, from the Slitherblade naga"},{["map"]=1443,["itemName"]="Gem of the Serpent",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:20:3",["t"]="use",["y"]=0.067,["x"]=0.282,["title"]="Book of the Ancients",["item"]=15766,["quest"]=6027,["note"]="Gem of the Serpent, on the Serpent Statue"},{["map"]=1443,["itemName"]="Book of the Ancients",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=12369,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:goal:20:4",["y"]=0.0667,["x"]=0.2824,["count"]=1,["from"]="Lord Kragaru",["quest"]=6027,["item"]=15803,["fromKind"]="npc",["title"]="Book of the Ancients"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/30-40/06b-desolace:step:20",["text"]="Sar'theris Strand: kill these as you meet them",["detail"]="The Slitherblade naga hold the north-west coast north of Azore Aldamort's tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to Ranazjar Isle off the far northern tip and use the G