ame"]="Shizzle",["x"]=0.44229999999999997,["title"]="Shizzle's Flyer",["minLevel"]=49,["qlvl"]=51,["quest"]=4503,["y"]=0.1159},{["map"]=1449,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:13:6",["t"]="getfp",["npc"]=10583,["npcName"]="Gryfe",["x"]=0.4523,["location"]="Marshal's Refuge",["y"]=0.0583,["node"]=79,["area"]=541},{["map"]=1449,["optional"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:13:7",["t"]="turnin",["npc"]=9270,["npcName"]="Williden Marshal",["x"]=0.4395,["title"]="Williden's Journal",["quest"]=3884,["y"]=0.07139999999999999},{["map"]=1449,["note"]="Linken, at the back of the refuge",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:13:8",["t"]="turnin",["npc"]=8737,["npcName"]="Linken",["x"]=0.44659999999999994,["title"]="It's a Secret to Everybody",["quest"]=3845,["y"]=0.081},{["map"]=1449,["note"]="Ends with Donova Snowden in Winterspring: keep it",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:13:9",["t"]="accept",["npc"]=8737,["y"]=0.081,["x"]=0.44659999999999994,["title"]="It's a Secret to Everybody",["minLevel"]=47,["pre"]={3845},["qlvl"]=52,["quest"]=3908,["npcName"]="Linken"},{["map"]=1449,["note"]="J.D. Collie, at the back of the cave; below ground",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:13:10",["t"]="accept",["npc"]=9117,["npcName"]="J.D. Collie",["x"]=0.4192,["title"]="Crystals of Power",["minLevel"]=47,["qlvl"]=53,["quest"]=4284,["y"]=0.027000000000000003},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:20:8",["text"]="Spark Nilminer, Hol'anyee Marshal, Williden Marshal and Karna Remtravel have quests among mobs of 51-55: leave them for the later Un'Goro visit, at about 56.",["t"]="note",["soloSpeedrun"]=true}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:step:20",["text"]="Marshal's Refuge",["detail"]="Ride north-west to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and Un'Goro Dirt Pile you pass from here on."},{["goals"]={{["itemName"]="Bloodpetal",["item"]=11316,["quest"]=4141,["map"]=1449,["fromId"]=6509,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:21:1",["t"]="collect",["fromAlso"]="Bloodpetal Flayer",["title"]="Muigin and Larion",["y"]=0.35,["x"]=0.5660000000000001,["count"]=15,["lvl"]=52,["from"]="Bloodpetal Lasher",["note"]="Bloodpetal, from the Lashers and Threshers",["fromKind"]="npc",["fromAlsoId"]=6510},{["map"]=1449,["itemName"]="Un'Goro Soil",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:21:2",["t"]="collect",["carriedTo"]="forever/alliance/50-60/01-burning-steppes",["y"]=0.35,["x"]=0.5660000000000001,["title"]="Un'Goro Soil",["fromNpcsAt"]="1;1;;;1;;1;;1;;1;2;2;2;;1;2;1;2;;3,5;;2;2;;2;6,2;2;4,3,5,6;2",["count"]=20,["note"]="Un'Goro Soil, from the Threshers and the dirt piles",["quest"]=3764,["item"]=11018},{["map"]=1449,["itemName"]="Webbed Pterrordax Scale",["oi"]=2,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:21:3",["t"]="collect",["item"]=11831,["y"]=0.353,["x"]=0.5770000000000001,["title"]="Shizzle's Flyer",["lvl"]=50,["note"]="Webbed Pterrordax Scale, Fledgling Pterrordax",["fromNpcsAt"]="1;1;1;2;1;1;1;2;2",["quest"]=4503,["count"]=8},{["map"]=1449,["itemName"]="Webbed Diemetradon Scale",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:21:4",["t"]="collect",["y"]=0.353,["x"]=0.5770000000000001,["title"]="Shizzle's Flyer",["lvl"]=52,["item"]=11830,["count"]=8,["quest"]=4503,["note"]="Webbed Diemetradon Scale, Young Diemetradon"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:step:21",["text"]="Fire Plume Ridge and the eastern jungle",["detail"]="Ride east into the eastern jungle: Bloodpetal Lashers and Threshers (48-50) drop the petals and Un'Goro Soil. Crystal clusters stand all over the crater, many around the foot of Fire Plume Ridge: take a few extra of each colour.\nCareful: the Living Blazes (54-55) walk the top of Fire Plume Ridge, and the Bloodpetal Flayers and Trappers (51-53) hold the jungle's south: take your crystals from the ridge's foot and your petals in the north.\nShizzle's scales: the Fledgling Pterrordax (48-50) glide over the north-east of the jungle and the Young Diemetradons (49-50) graze beside them. There are only ten of those: the Diemetradons (51) on the jungle's western edge, a short way west of the Threshers, drop the scales too. They are a level over you: take them one at a time."},{["goals"]={{["map"]=1449,["itemName"]="Blue Power Crystal",["oi"]=4,["soloSpeedrun"]=true,["fromId"]=164658,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:22:1",["y"]=0.21100000000000002,["x"]=0.722,["count"]=7,["from"]="Blue Power Crystal",["quest"]=4284,["item"]=11184,["fromKind"]="object",["title"]="Crystals of Power"},{["map"]=1449,["itemName"]="Green Power Crystal",["oi"]=3,["soloSpeedrun"]=true,["fromId"]=164659,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:22:2",["y"]=0.21100000000000002,["x"]=0.722,["count"]=7,["from"]="Green Power Crystal",["quest"]=4284,["item"]=11185,["fromKind"]="object",["title"]="Crystals of Power"},{["map"]=1449,["itemName"]="Red Power Crystal",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=164660,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:22:3",["y"]=0.21100000000000002,["x"]=0.722,["count"]=7,["from"]="Red Power Crystal",["quest"]=4284,["item"]=11186,["fromKind"]="object",["title"]="Crystals of Power"},{["map"]=1449,["itemName"]="Yellow Power Crystal",["oi"]=2,["soloSpeedrun"]=true,["fromId"]=164661,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:goal:22:4",["y"]=0.21100000000000002,["x"]=0.722,["count"]=7,["from"]="Yellow Power Crystal",["quest"]=4284,["item"]=11188,["fromKind"]="object",["title"]="Crystals of Power"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:step:22",["text"]="Lakkari Tar Pits",["detail"]="Crystal clusters stand all over the crater. The pits' Tar Lords (53-54) and the oozes around them (50-54) are over you: take the clusters on the jungle's north-eastern edge, among the Lashers and young beasts (48-50)."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/40-50/07-un-goro-crater:step:23",["text"]="Marshal's Refuge",["goals"]={{["map"]=1449,["note"]="J.D. Collie, below ground",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:16:1",["t"]="turnin",["npc"]=9117,["npcName"]="J.D. Collie",["x"]=0.4192,["title"]="Crystals of Power",["quest"]=4284,["y"]=0.027000000000000003},{["map"]=1449,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:16:5",["t"]="turnin",["npc"]=9119,["npcName"]="Muigin",["x"]=0.4294,["title"]="Muigin and Larion",["quest"]=4141,["y"]=0.0964},{["map"]=1449,["note"]="For Gregan Brewspewer in Feralas: keep it",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:16:6",["t"]="accept",["npc"]=9119,["y"]=0.0964,["x"]=0.4294,["title"]="A Visit to Gregan",["minLevel"]=47,["pre"]={4141},["qlvl"]=52,["quest"]=4142,["npcName"]="Muigin"},{["map"]=1449,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/40-50/07-un-goro-crater:25:1",["t"]="turnin",["npc"]=9998,["npcName"]="Shizzle",["x"]=0.44229999999999997,["title"]="Shizzle's Flyer",["quest"]=4503,["y"]=0.1159},{["soloSpeedru