illas on Ironstone Plateau",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/04-western-plaguelands:115:3",["t"]="accept",["npc"]=9619,["npcName"]="Torwa Pathfinder",["x"]=0.7164,["title"]="The Apes of Un'Goro",["minLevel"]=47,["qlvl"]=55,["quest"]=4289,["y"]=0.7595999999999999},{["map"]=1449,["optional"]=true,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/04-western-plaguelands:goal:110:4",["t"]="turnin",["npc"]=9619,["npcName"]="Torwa Pathfinder",["x"]=0.7164,["title"]="Microcrystal Contamination",["y"]=0.7595999999999999,["quest"]=87494,["note"]="Microcrystal Contamination, if a ravasaur dropped the scale since the first visit"},{["map"]=1449,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/04-western-plaguelands:goal:110:5",["t"]="accept",["npc"]=9619,["npcName"]="Torwa Pathfinder",["x"]=0.7164,["title"]="Uncanny Crystal",["minLevel"]=50,["qlvl"]=55,["quest"]=87492,["y"]=0.7595999999999999}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/04-western-plaguelands:step:110",["text"]="Torwa Pathfinder",["detail"]="Torwa Pathfinder camps at the foot of the ramp into the crater."},{["goals"]={{["map"]=1449,["itemName"]="Damaged Blue Crystal",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=672518,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/04-western-plaguelands:goal:111:1",["y"]=0.752,["x"]=0.6629999999999999,["count"]=1,["from"]="Damaged Blue Crystal",["quest"]=87492,["item"]=280417,["fromKind"]="object",["title"]="Uncanny Crystal"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/04-western-plaguelands:step:111",["text"]="Damaged Blue Crystal",["detail"]="The Damaged Blue Crystal is a short ride west of Torwa Pathfinder's camp."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/04-western-plaguelands:step:112",["text"]="Torwa P