]="npc",["lvl"]=52},{["itemName"]="Un'Goro Thunderer Pelt",["soloWhen"]={{["k"]="onquest",["q"]={4289}}},["item"]=11480,["quest"]=4289,["map"]=1449,["oi"]=3,["soloSpeedrun"]=true,["fromId"]=6516,["t"]="collect",["id"]="solo:forever/alliance/50-60/04-western-plaguelands:111:3",["y"]=0.1967,["x"]=0.6263000000000001,["title"]="The Apes of Un'Goro",["from"]="Un'Goro Thunderer",["count"]=2,["note"]="Un'Goro Thunderer Pelt; below ground",["fromKind"]="npc",["lvl"]=53}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/04-western-plaguelands:111",["text"]="Ironstone Plateau: kill these as you meet them",["soloWhen"]={{["k"]="onquest",["q"]={4289}}},["detail"]="The gorillas live on Ironstone Plateau, east of Marshal's Refuge. Keep their pelts for Torwa Pathfinder. Stay out of the deepest cave: U'cha is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."},{["goals"]={{["map"]=1449,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/04-western-plaguelands:118:1",["t"]="turnin",["npc"]=9619,["soloWhen"]={{["k"]="onquest",["q"]={4289}}},["npcName"]="Torwa Pathfinder",["x"]=0.7164,["title"]="The Apes of Un'Goro",["quest"]=4289,["y"]=0.7595999999999999},{["map"]=1449,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/04-western-plaguelands:118:2",["t"]="accept",["npc"]=9619,["soloWhen"]={{["k"]="onquest",["q"]={4289}}},["y"]=0.7595999999999999,["x"]=0.7164,["title"]="The Mighty U'cha",["minLevel"]=50,["pre"]={4289},["qlvl"]=55,["quest"]=4301,["npcName"]="Torwa Pathfinder"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/04-western-plaguelands:118",["text"]="Torwa Pathfinder",["soloWhen"]={{["k"]="onquest",["q"]={4289}}}},{["goals"]={{["map"]=1449,["itemName"]="U'cha's Pelt",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=9622,["t"]="collect",["id"]="solo:forever/alliance/50-60/04-western-plaguelands:119:1",["