"]={{["map"]=1448,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:4:1",["t"]="turnin",["npc"]=10922,["npcName"]="Greta Mosshoof",["x"]=0.5121,["title"]="Cleansed Water Returns to Felwood",["quest"]=5159,["y"]=0.8210999999999999},{["map"]=1448,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:4:3",["t"]="turnin",["npc"]=9116,["npcName"]="Eridan Bluewind",["x"]=0.5135000000000001,["title"]="Felbound Ancients",["quest"]=4441,["y"]=0.8151},{["map"]=1448,["note"]="Inside",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:4:4",["t"]="accept",["npc"]=9116,["y"]=0.8151,["x"]=0.5135000000000001,["title"]="Purified!",["minLevel"]=49,["pre"]={4441},["qlvl"]=54,["quest"]=4442,["npcName"]="Eridan Bluewind"},{["map"]=1448,["note"]="Wait a moment for Eridan Bluewind",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:4:5",["t"]="turnin",["npc"]=9116,["npcName"]="Eridan Bluewind",["x"]=0.5135000000000001,["title"]="Purified!",["quest"]=4442,["y"]=0.8151},{["map"]=1448,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:4:6",["t"]="turnin",["npc"]=9116,["npcName"]="Eridan Bluewind",["x"]=0.5135000000000001,["title"]="Linken's Memory",["quest"]=3942,["y"]=0.8151},{["map"]=1448,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:4:7",["t"]="accept",["npc"]=9116,["y"]=0.8151,["x"]=0.5135000000000001,["title"]="Silver Heart",["minLevel"]=47,["pre"]={3942},["qlvl"]=54,["quest"]=4084,["npcName"]="Eridan Bluewind"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:4",["text"]="The Emerald Sanctuary",["detail"]="From Talrendis Point ride into Felwood: the Emerald Sanctuary is the druids' camp on the road just past the Ashenvale border."},{["goals"]={{["map"]=1448,["itemName"]="Silvery Claws",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/06-silithus:goal:5:1",["t"]="collect",["item"]=11172,["spread"]=true,["y"]=0.8062,["x"]=0.5142,["count"]=11,["lvl"]=50,["note"]="Angerclaw bears and Felpaw wolves",["title"]="Silver Heart",["quest"]=4084,["fromNpcsAt"]="1;1;2;1,2;4,5;4;4;5;3,6;5;3,6;3,6;1,2;1;7;1;2,7;2;1;1;1,2;8;2,7;1;2;1;2;2,1;2;2;2;1,2;2,1,7;2;1;2;8;5;1;2,1,8;2;5,4;1,8;2;4;4;2;4;4;5;5,4;5;4,5;4;4,5;5;5;5;5,4;4;3,6;3,6;3;3;5;4,5;5;5;4;4,5;6,3;6,3;3;3,4,5;4;3;3,6;3;3;6;3;3;3"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/06-silithus:step:5",["text"]="Shadow Hold braziers",["detail"]="Shadow Hold is the cave at the back of Jaedenar, west of the road. Use the Purified Moonwell Water on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the Silvery Claws.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended.\nThe Jaedenar Darkweavers, Warlocks and Enforcers in here drop a Blood Red Key, about one kill in thirty: keep killing them until it drops. It opens the cell of Arko'narin, the night elf held in the cave."},{["goals"]={{["map"]=1448,["x"]=0.354,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:6:1",["t"]="goto",["y"]=0.591,["soloWhen"]={{["k"]="onquest",["q"]={5203}}}}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:6",["text"]="Arko'narin",["soloWhen"]={{["k"]="onquest",["q"]={5203}}},["detail"]="Lead her out of Shadow Hold and keep her alive until she is outside the cave: clear the way back first."},{["goals"]={},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:7",["text"]="The Emerald Sanctuary",["superseded"]=true},{["goals"]={{["map"]=1448,["itemName"]="Silvery Claws",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/06-silithus:goal:8:1",["t"]="collect",["item"]=11172,["y"]=0.8062,["x"]=0.5142,["title"]="Silver Heart",["lvl"]=50,["spread"]=true,["fromNpcsAt"]="1;1;2;1,2;4,5;4;4;5;3,6;5;3,6;3,6;1,2;1;7;1;2,7;2;1;1;1,2;8;2,7;1;2;1;2;2,1;2;2;2;1,2;2,1,7;2;1;2;8;5;1;2,1,8;2;5,4;1,8;2;4;4;2;4;4;5;5,4;5;4,5;4;4,5;5;5;5;5,4;4;3,6;3,6;3;3;5;4,5;5;5;4;4,5;6,3;6,3;3;3,4,5;4;3;3,6;3;3;6;3;3;3",["quest"]=4084,["count"]=11},{["itemName"]="Irontree Heart",["item"]=11173,["quest"]=4084,["map"]=1448,["fromId"]=7138,["oi"]=2,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/06-silithus:goal:8:2",["fromAlso"]="Irontree Stomper",["t"]="collect",["title"]="Silver Heart",["y"]=0.2984,["x"]=0.4851,["count"]=1,["from"]="Irontree Wanderer",["note"]="Irontree Stompers",["lvl"]=53,["fromKind"]="npc",["fromAlsoId"]=7139}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/50-60/06-silithus:step:8",["text"]="Irontree Woods",["detail"]="Follow the road north to Irontree Woods. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north.\nCareful: Ancient Irontree Walkers, level 59 elites, stand among the treants in the middle of Irontree Woods: take the Stompers on the north side (about 48,21)."},{["goals"]={{["map"]=1448,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:9:1",["t"]="accept",["npc"]=9598,["escort"]=true,["npcName"]="Arei",["x"]=0.49570000000000003,["minLevel"]=49,["title"]="Ancient Spirit",["pre"]={4442},["qlvl"]=56,["quest"]=4261,["y"]=0.29600000000000004},{["title"]="Ancient Spirit",["escort"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:9:2",["t"]="complete",["quest"]=4261,["objs"]={{["count"]=1,["text"]="Help Arei get to Safety"}}}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:9",["text"]="Arei",["detail"]="Arei waits in Irontree Woods. Escort her out of the woods and keep her alive.\nCareful: Three Toxic Horrors ambush you soon after the escort starts."},{["goals"]={{["map"]=1448,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:10:1",["t"]="turnin",["y"]=0.0584,["x"]=0.602,["title"]="Falling to Corruption",["objName"]="Deadwood Cauldron",["quest"]=5084,["object"]=176091},{["map"]=1448,["note"]="Mystery Goo: Donova Snowden in Winterspring, keep it",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:10:2",["t"]="accept",["qlvl"]=56,["y"]=0.0584,["x"]=0.602,["title"]="Mystery Goo",["objName"]="Deadwood Cauldron",["pre"]={5084},["minLevel"]=52,["quest"]=5085,["object"]=176091}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:10",["text"]="Felpaw Village",["detail"]="Ride north to the Deadwood furbolgs' village by the Timbermaw Hold cave mouth."},{["goals"]={},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:11",["text"]="A Final Blow",["superseded"]=true,["detail"]="Back into Shadow Hold: Moora and Salia guard Shadow Lord Fel'dan in its deepest chamber. The succubus Rakaiah waits on the way, with Trey Lightforge's remains beside her.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."},{["goals"]={{["map"]=1448,["note"]="Eridan Bluewind, inside",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:12:1",["t"]="turnin",["npc"]=9116,["npcName"]="Eridan Bluewind",["x"]=0.5135000000000001,["title"]="Silver Heart",["quest"]=4084,["y"]=0.8151},{["map"]=1448,["note"]="Keep the Book of Aquor, the claws and the heart he hands back",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:12:2",["t"]="accept",["npc"]=9116,["y"]=0.8151,["x"]=0.5135000000000001,["title"]="Aquementas",["minLevel"]=47,["pre"]={4084},["qlvl"]=54,["quest"]=4005,["npcName"]="Eridan Bluewind"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:12",["text"]="The Emerald Sanctuary",["detail"]="Ride back south along the road to the Sanctuary."},{["goals"]={{["map"]=1440,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/50-60/06-silithus:36:2",["t"]=