ue,["id"]="solo:forever/alliance/dwarf/01-dun-morogh:123",["text"]="Goldshire",["detail"]="Leave Stormwind by the main gate and follow the road south to Goldshire: east Elwynn comes before Westfall."}},["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; adapted Forever solo leveling plan",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/dwarf/01-dun-morogh",["max"]=14,["next"]="solo:forever/alliance/02-westfall",["zoneName"]="Dun Morogh",["min"]=1,["availability"]="source-listed",["races"]={"Dwarf"},["category"]="Leveling",["faction"]="Alliance",["name"]="Dun Morogh (solo 1-14)",["refreshRevision"]="forever-20261117-b753c783",["zone"]=1426} end},
