eded"]=true,["soloWhen"]={{["k"]="onquest",["q"]={96044}},{["k"]="complete",["q"]=96044}}},{["goals"]={{["map"]=1426,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:27:1",["t"]="accept",["npc"]=1378,["npcName"]="Pilot Bellowfiz",["x"]=0.4943,["title"]="Stocking Jetsteam",["minLevel"]=2,["qlvl"]=6,["quest"]=317,["y"]=0.4841},{["map"]=1426,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:27:2",["t"]="accept",["npc"]=1377,["npcName"]="Pilot Stonegear",["x"]=0.4962,["title"]="The Grizzled Den",["minLevel"]=4,["qlvl"]=7,["quest"]=313,["y"]=0.4861},{["map"]=1426,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:27:3",["t"]="turnin",["npc"]=1376,["npcName"]="Beldin Steelgrill",["x"]=0.5044,["title"]="Tools for Steelgrill",["quest"]=400,["y"]=0.49090000000000006},{["map"]=1426,["note"]="Loslor Rudge, beside him",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:27:4",["t"]="accept",["npc"]=1694,["npcName"]="Loslor Rudge",["x"]=0.5008,["title"]="Ammo for Rumbleshot",["minLevel"]=5,["qlvl"]=6,["quest"]=5541,["y"]=0.49420000000000003}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:27",["text"]="Steelgrill's Depot",["detail"]="Follow the road north-east from Kharanos to the depot below the Ironforge road."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/gnome/01-dun-morogh:step:28",["text"]="Yarr Hammerstone",["superseded"]=true,["soloWhen"]={{["k"]="onquest",["q"]={96046}},{["k"]="complete",["q"]=96046}}},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/gnome/01-dun-morogh:step:29",["text"]="Bronk Guzzlegear",["superseded"]=true,["soloWhen"]={{["k"]="onquest",["q"]={96058}},{["k"]="complete",["q"]=96058}}},{["goals"]={{["map"]=1426,["itemName"]="Rumbleshot's Ammo",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=176785,["t"]="collect",["id"]="solo:forever/alliance/gn