lo:forever/alliance/gnome/01-dun-morogh:43:2",["t"]="accept",["npc"]=1374,["y"]=0.4573,["x"]=0.3019,["title"]="Return to Bellowfiz",["minLevel"]=2,["pre"]={319},["qlvl"]=8,["quest"]=320,["npcName"]="Rejold Barleybrew"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1426,["x"]=0.4257,["y"]=0.5468,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:31:3",["t"]="goto",["text"]="Grizzled Den",["area"]=136},{["map"]=1426,["itemName"]="Flintfire's Shipment",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=672508,["t"]="collect",["id"]="solo:forever/alliance/gnome/01-dun-morogh:32:1",["y"]=0.528,["x"]=0.418,["count"]=8,["from"]="Flintfire's Shipment",["quest"]=98321,["item"]=280413,["fromKind"]="object",["title"]="Flintfire's Shipment"},{["map"]=1426,["itemName"]="Sack of Fish",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=271587,["t"]="collect",["id"]="solo:forever/alliance/gnome/01-dun-morogh:44:2",["quest"]=98326,["y"]=0.4879,["x"]=0.3933,["item"]=280426,["from"]="Frosthowl",["title"]="Frosthowl",["count"]=1,["fromKind"]="npc",["note"]="Sack of Fish: Frosthowl, at the back"},{["itemName"]="Wendigo Mane",["item"]=2671,["quest"]=313,["map"]=1426,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=1134,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/gnome/01-dun-morogh:goal:40:4",["count"]=8,["y"]=0.488,["x"]=0.39049999999999996,["title"]="The Grizzled Den",["lvl"]=8,["fromAlso"]="Wendigo",["from"]="Young Wendigo",["fromKind"]="npc",["fromAlsoId"]=1135},{["map"]=1426,["x"]=0.429,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:32:3",["text"]="Mountaineer Cornelius",["y"]=0.496,["t"]="goto"},{["title"]="Secure the Mountain",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:32:4",["t"]="complete",["objs"]={{["count"]=1,["text"]="Mountaineer Cornelius found"}},["quest"]=98319}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/gnome/01-dun-morogh:step:40",["text"]="Grizzled Den",["detail"]="Back to the Grizzled Den, the wendigo cave south-west of Kharanos where Mountaineer Gretchen camps. Flintfire's shipments lie on the cave floor, Mountaineer Cornelius is missing deep inside, and Frosthowl (level 9) keeps the Sack of Fish at the back.\nCareful: Wendigos, Elder Wendigos and Wendigo Shamans (up to level 8) stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks avoids this."},{["id"]="solo:forever/alliance/gnome/01-dun-morogh:33",["text"]="Mountaineer Gretchen",["goals"]={{["map"]=1426,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:33:1",["t"]="turnin",["npc"]=271546,["npcName"]="Mountaineer Gretchen",["x"]=0.441,["title"]="Secure the Mountain",["quest"]=98319,["y"]=0.5707},{["map"]=1426,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:33:2",["t"]="accept",["npc"]=271546,["y"]=0.5707,["x"]=0.441,["title"]="Secure the Mountain",["minLevel"]=4,["pre"]={98319},["qlvl"]=8,["quest"]=98323,["npcName"]="Mountaineer Gretchen"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1426,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:37:1",["t"]="turnin",["npc"]=1252,["npcName"]="Senir Whitebeard",["x"]=0.4673,["title"]="Secure the Mountain",["quest"]=98323,["y"]=0.5383},{["map"]=1426,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:37:2",["t"]="accept",["npc"]=1252,["y"]=0.5383,["x"]=0.4673,["title"]="Frostmane Hold",["minLevel"]=7,["pre"]={420},["qlvl"]=9,["quest"]=287,["npcName"]="Senir Whitebeard"},{["map"]=1426,["note"]="Tognus Flintfire, below ground",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:37:3",["t"]="turnin",["npc"]=1241,["npcName"]="Tognus Flintfire",["x"]=0.4534,["title"]="Flintfire's Shipment",["quest"]=98321,["y"]=0.5194},{["map"]=1426,["itemName"]="Thunder Ale",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/gnome/01-dun-morogh:45:3",