id"]="solo:forever/alliance/human/01-elwynn-forest:50:1",["t"]="goto",["text"]="Fargodeep Mine",["area"]=57},{["map"]=1429,["itemName"]="Bernice's Necklace",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=327,["t"]="collect",["id"]="solo:forever/alliance/human/01-elwynn-forest:50:2",["fromKind"]="npc",["y"]=0.7803,["x"]=0.4171,["title"]="Goldtooth",["from"]="Goldtooth",["item"]=981,["note"]="Bernice's Necklace; below ground",["quest"]=87,["count"]=1},{["map"]=1429,["itemName"]="Westfall Deed",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/human/01-elwynn-forest:goal:50:3",["fromNpcsAt"]="1;2,3,6;1;4;4;1;1;1;7;1;1;1;1;1;1;1,4;1,4;4,1;1;1,5,8;4;4;4",["y"]=0.7493000000000001,["x"]=0.4437,["item"]=1972,["lvl"]=9,["count"]=1,["optional"]=true,["spread"]=true,["t"]="collect"},{["optional"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/human/01-elwynn-forest:50:4",["t"]="accept",["title"]="Furlbrow's Deed",["item"]=1972,["qlvl"]=9,["minLevel"]=8,["quest"]=184,["itemName"]="Westfall Deed"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/human/01-elwynn-forest:step:50",["text"]="Goldtooth",["detail"]="Goldtooth is inside the Fargodeep Mine, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a Westfall Deed now and then: right-click it.\nCareful: Nimsy (6), a kobold deep in the mine, is elite, and Narg the Taskmaster (10, rare) walks the tunnels: pull the kobolds one at a time."},{["goals"]={{["map"]=1429,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/human/01-elwynn-forest:51:1",["t"]="turnin",["npc"]=241,["npcName"]="Remy \"Two Times\"",["x"]=0.4214,["title"]="Gold Dust Exchange",["quest"]=47,["y"]=0.6726000000000001},{["map"]=1429,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/human/01-elwynn-forest:51:2",["t"]="turnin",["npc"]=241,["npcName"]="Remy \"Two Times\"",["x"]=0.4214,