,["fromId"]=6128,["t"]="collect",["id"]="solo:forever/alliance/nightelf/01-teldrassil:69:1",["y"]=0.636,["x"]=0.47200000000000003,["count"]=1,["from"]="Vorlus Vilehoof",["quest"]=1683,["item"]=6805,["fromKind"]="npc",["title"]="Vorlus Vilehoof"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/nightelf/01-teldrassil:69",["text"]="Vorlus Vilehoof",["only"]={["classes"]={"WARRIOR"}},["detail"]="Back out of the city gate and east along the road: Vorlus Vilehoof stands south of it, by Ban'ethil Hollow. Bring his horn back to Elanaria."},{["goals"]={{["map"]=1457,["x"]=0.7070000000000001,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/nightelf/01-teldrassil:70:1",["text"]="Elanaria",["y"]=0.45399999999999996,["t"]="goto"}},["soloSpeedrun"]=true,["id"]="solo:forever/alliance/nightelf/01-teldrassil:70",["text"]="Back to Darnassus",["only"]={["classes"]={"WARRIOR"}}},{["goals"]={{["map"]=1457,["note"]="Elanaria, on the Warrior's Terrace: Defensive Stance",["soloSpeedrun"]=true,["id"]="solo:forever/alliance/nightelf/01-teldrassil:71:1",["t"]="turnin",["npc"]=4088,["npcName"]="Elanaria",["x"]=0.573,["title"]="Vorlus Vilehoof",["y"]=0.3461,["quest"]=1683,["only"]={["classes"]={"WARRIOR"}}},{["map"]=1457,["endNpcs"]={10118},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/alliance/nightelf/01-teldrassil:goal:75:2",["t"]="accept",["xp"]=210,["only"]={["classes"]={"PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"}},["npcName"]="Mydrannul",["x"]=0.7068000000000001,["minLevel"]=10,["qlvl"]=10,["y"]=0.45380000000000004,["title"]="Nessa Shadowsong",["quest"]=6344,["npc"]=4241},{["map"]=1457,["itemName"]="Lunar Pendant",["oi"]=3,["soloSpeedrun"]=true,["id"]="solo:forever/alliance/nightelf/01-teldrassil:71:3",["t"]="use",["y"]=0.1535,["x"]=0.6646,["title"]="Eyes of the Sentinels",["item"]=279378,["quest"]=98067,["note"]="Lunar Pendant: the inn on the Craftsmen's Terrace"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b75