]=0.30870000000000003},{["map"]=1413,["note"]="Darsok Swiftdagger: the harpies come later, in the Dry Hills",["soloSpeedrun"]=true,["id"]="solo:forever/horde/02-the-barrens:3:12",["t"]="accept",["npc"]=3449,["npcName"]="Darsok Swiftdagger",["x"]=0.5162,["title"]="Harpy Raiders",["minLevel"]=12,["qlvl"]=15,["quest"]=867,["y"]=0.309}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/02-the-barrens:step:4",["text"]="The Crossroads",["only"]={["races"]={"Orc","Troll"}},["detail"]="You arrive from Far Watch Post. Zargh and Sergra Darkthorn stand by the inn, Helbrim and Gazrog by the north gate; Devrak, Thork and Darsok Swiftdagger on the tower platform."},{["goals"]={{["map"]=1413,["soloSpeedrun"]=true,["id"]="solo:forever/horde/02-the-barrens:4:1",["t"]="turnin",["npc"]=5878,["npcName"]="Thun'grim Firegaze",["x"]=0.5722999999999999,["title"]="Thun'grim Firegaze",["quest"]=1502,["y"]=0.3034},{["map"]=1413,["soloSpeedrun"]=true,["id"]="solo:forever/horde/02-the-barrens:4:2",["t"]="accept",["npc"]=5878,["y"]=0.3034,["x"]=0.5722999999999999,["title"]="Forged Steel",["minLevel"]=10,["pre"]={1502},["qlvl"]=10,["quest"]=1503,["npcName"]="Thun'grim Firegaze"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/02-the-barrens:step:5",["text"]="Thun'grim Firegaze",["only"]={["classes"]={"WARRIOR"},["races"]={"Orc","Troll","Tauren"}},["detail"]="Thun'grim Firegaze camps beside the road east toward Ratchet."},{["goals"]={{["map"]=1413,["itemName"]="Forged Steel Bars",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=58369,["t"]="collect",["id"]="solo:forever/horde/02-the-barrens:5:1",["quest"]=1503,["y"]=0.26649999999999996,["x"]=0.5505,["item"]=6534,["from"]="Stolen Iron Chest",["title"]="Forged Steel",["count"]=1,["only"]={["classes"]={"WARRIOR"}},["fromKind"]="object"},{["itemName"]="Fire Tar",["item"]=5026,["quest"]=1525,["fromId"]=3267,["map"]=1413,["only"]={["classes"]={"SHAMAN"}},["oi"]=1,["soloSpeedrun"]=true,["id"]=