x"]=0.5621,["minLevel"]=16,["qlvl"]=16,["pre"]={27},["title"]="Trial of the Lake",["only"]={["races"]={"Tauren","Skyborne"}},["y"]=0.3064},{["map"]=1450,["itemName"]="Shrine Bauble",["soloSpeedrun"]=true,["fromId"]=177785,["t"]="collect",["y"]=0.46399999999999997,["x"]=0.547,["item"]=15877,["from"]="Bauble Container",["id"]="solo:forever/horde/02-the-barrens:58:5",["count"]=1,["fromKind"]="object",["note"]="Shrine Bauble, from a Bauble Container in the lake"},{["map"]=1450,["itemName"]="Shrine Bauble",["soloSpeedrun"]=true,["id"]="solo:forever/horde/02-the-barrens:58:6",["t"]="use",["y"]=0.414,["x"]=0.36,["item"]=15877,["note"]="At the Shrine of Remulos"},{["objs"]={{["count"]=1,["text"]="Shrine Of Remulos"}},["title"]="Trial of the Lake",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/02-the-barrens:goal:45:7",["t"]="complete",["quest"]=28,["only"]={["races"]={"Tauren","Skyborne"}}},{["map"]=1450,["note"]="Tajarri, at the Shrine of Remulos",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/02-the-barrens:goal:45:8",["t"]="turnin",["npc"]=11799,["npcName"]="Tajarri",["x"]=0.3652,["title"]="Trial of the Lake",["y"]=0.401,["quest"]=28,["only"]={["races"]={"Tauren","Skyborne"}}},{["map"]=1450,["note"]="Trial of the Sea Lion, carried: one half pendant in the Sludge Fen in this guide, the other underwater off Silverpine on the way to Hillsbrad at 21; the pendant is handed in after Hillsbrad",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/02-the-barrens:goal:45:9",["t"]="accept",["npc"]=11799,["title"]="Trial of the Sea Lion",["npcName"]="Tajarri",["x"]=0.3652,["minLevel"]=16,["quest"]=30,["pre"]={28},["qlvl"]=16,["only"]={["races"]={"Tauren","Skyborne"}},["y"]=0.401},{["note"]="Bunthen Plainswind in Nighthaven flies druids there",["id"]="solo:forever/horde/02-the-barrens:58:10",["soloSpeedrun"]=true,["location"]="Thunder Bluff",["t"]="fly",["node"]=22,["area"]=1638}},[