d"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:76:2",["t"]="accept",["npc"]=260391,["y"]=0.39799999999999996,["x"]=0.912,["title"]="Smuggler's Bargain",["minLevel"]=38,["pre"]={95293},["qlvl"]=42,["quest"]=95294,["npcName"]="Captain Haynes"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:step:76",["text"]="Captain Bentcoin",["detail"]="East along the cliffs to the far end of the pirates' camp: Captain Bentcoin waits by the water, Captain Haynes beside him."},{["goals"]={{["map"]=2548,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:77:1",["t"]="turnin",["npc"]=259961,["npcName"]="Wharfmaster Whizzbuzz",["x"]=0.7945,["title"]="Unchecked Expansion",["quest"]=95122,["y"]=0.5271},{["map"]=2548,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:77:2",["t"]="turnin",["npc"]=259961,["npcName"]="Wharfmaster Whizzbuzz",["x"]=0.7945,["title"]="A Blast Ye Scurvy Dogs!",["quest"]=95123,["y"]=0.5271},{["map"]=2548,["note"]="See Ya, Scallywags!",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:77:3",["t"]="accept",["npc"]=259961,["y"]=0.5271,["x"]=0.7945,["title"]="See Ya, Scallywags!",["minLevel"]=38,["pre"]={95123},["qlvl"]=44,["quest"]=95165,["npcName"]="Wharfmaster Whizzbuzz"},{["map"]=2548,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:77:4",["t"]="turnin",["npc"]=255897,["npcName"]="Friz Frazzlespark",["x"]=0.7709999999999999,["title"]="Smuggler's Bargain",["quest"]=95294,["y"]=0.529},{["map"]=2548,["note"]="Friz Frazzlespark: Shipping and Handling, for Wharfmaster Steamfizzle at Steamwheedle Port in the Feralas & Tanaris guide",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:77:5",["t"]="accept",["npc"]=255897,["y"]=0.529,["x"]=0.7709999999999999,["title"]="Shipping and Handling",["minLevel"]=36,["pre"]={95294},["qlvl"]=40,["quest"]=95296,["npcName"]="Friz Frazzlespark"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:step:77",["text"]="Powderfuse Port",["detail"]="Back to the port."},{["goals"]={{["map"]=2548,["itemName"]="Remote Explosive Charge",["oi"]=3,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:78:1",["t"]="use",["y"]=0.395,["x"]=0.909,["title"]="See Ya, Scallywags!",["item"]=268505,["quest"]=95165,["note"]="Remote Explosive Charge, the southern ship"},{["map"]=2548,["itemName"]="Remote Explosive Charge",["oi"]=2,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:78:2",["t"]="use",["y"]=0.29600000000000004,["x"]=0.9059999999999999,["title"]="See Ya, Scallywags!",["item"]=268505,["quest"]=95165,["note"]="the middle ship"},{["map"]=2548,["itemName"]="Remote Explosive Charge",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:78:3",["t"]="use",["y"]=0.258,["x"]=0.883,["title"]="See Ya, Scallywags!",["item"]=268505,["quest"]=95165,["note"]="the northern ship"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:step:78",["text"]="The pirates' ships",["detail"]="Out to the pirates' cliffs once more. Plant Whizzbuzz's charges on the three ships moored below the camp, south to north; Admiral Lamora stands by the middle one, with her loot chest beside her. Keep an eye out for Gul'gash on the way.\nCareful: Admiral Lamora is level 45, a level or two over you here: clear the deck around her first and come in with full health."},{["goals"]={{["map"]=2548,["itemName"]="Rotflesh Mushroom",["oi"]=2,["soloSpeedrun"]=true,["fromId"]=630588,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:79:1",["y"]=0.26,["x"]=0.7559999999999999,["count"]=8,["from"]="Rotflesh Mushroom",["quest"]=95261,["item"]=268664,["fromKind"]="object",["title"]="It Takes Guts"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:step:79",["text"]="Rotflesh Mushrooms",["detail"]="West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."},{["goals"]={{["map"]=2548,["itemName"]="Beast Entrails",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:80:1",["t"]="collect",["soloWhen"]={{["neg"]=true,["k"]="has",["item"]=268632,["n"]=15}},["y"]=0.498,["x"]=0.787,["title"]="It Takes Guts",["item"]=268632,["quest"]=95261,["count"]=15}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:step:80",["text"]="Finish the Beast Entrails",["soloWhen"]={{["neg"]=true,["k"]="has",["item"]=268632,["n"]=15}},["detail"]="South-east back towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. Gul'gash wanders down to this beach too."},{["goals"]={{["map"]=2548,["itemName"]="Beast Entrails",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/01b-riverglades:goal:81:1",["t"]="collect",["note"]="Most beasts in the Riverglades drop Beast Entrails for Argo Brinewhistle: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: Old Rot-Chum (elite, 42) wanders the shore and Ghostmaw (elite, 42) the river: take your beasts away from them. Collect these while following the outdoor loop; finish before this hand-in.",["y"]=0.5352,["x"]=0.7931,["title"]="It Takes Guts",["quest"]=95261,["item"]=268632,["count"]=15,["