t 50."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/02-feralas:step:13",["text"]="Fly to Grom'gol",["goals"]={{["map"]=1434,["x"]=0.268,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/02-feralas:goal:13:1",["text"]="Booty Bay flight master",["y"]=0.77,["t"]="goto"},{["soloSpeedrun"]=true,["location"]="Grom'gol",["t"]="fly",["node"]=20,["id"]="solo:forever/horde/40-50/02-feralas:2:2"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1434,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/02-feralas:goal:14:1",["t"]="turnin",["npc"]=2519,["npcName"]="Kin'weelay",["x"]=0.32270000000000004,["title"]="The Singing Crystals",["quest"]=589,["y"]=0.2771},{["map"]=1434,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/02-feralas:goal:14:2",["t"]="turnin",["npc"]=2465,["npcName"]="Far Seer Mok'thardin",["x"]=0.3212,["title"]="Mok'thardin's Enchantment",["quest"]=573,["y"]=0.2924}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/02-feralas:step:14",["text"]="Grom'gol Base Camp",["detail"]="The flight lands at Grom'gol: Kin'weelay and Far Seer Mok'thardin, then the zeppelin tower."},{["id"]="solo:forever/horde/40-50/02-feralas:3",["text"]="Zeppelin to Orgrimmar",["goals"]={{["map"]=1434,["x"]=0.314,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/02-feralas:3:1",["text"]="Zeppelin to Orgrimmar",["y"]=0.299,["t"]="goto"}},["soloSpeedrun"]=true},{["id"]="solo:forever/horde/40-50/02-feralas:4",["text"]="Orgrimmar",["goals"]={{["map"]=1454,["x"]=0.515,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/02-feralas:4:1",["text"]="The middle of Orgrimmar",["y"]=0.456,["t"]="goto"}},["soloSpeedrun"]=true},{["goals"]={{["zone"]=1454,["locations"]={{["map"]=1454,["x"]=0.48619999999999997,["y"]=0.46950000000000003,["only"]={["classes"]={"WARLOCK"}},["npc"]=3325,["npcName"]="Mirket"},{["map"]=1454,["x"]=0.