uest"]=1170,["npcName"]="Draz'Zilb"},{["map"]=1445,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:26:3",["t"]="turnin",["npc"]=4502,["npcName"]="Tharg",["x"]=0.3737,["title"]="Army of the Black Dragon",["quest"]=1168,["y"]=0.3139},{["map"]=1445,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:26:4",["t"]="turnin",["npc"]=4500,["npcName"]="Overlord Mok'Morokk",["x"]=0.3629,["title"]="The Brood of Onyxia",["quest"]=1170,["y"]=0.3141},{["map"]=1445,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:26:5",["t"]="accept",["npc"]=4500,["y"]=0.3141,["x"]=0.3629,["title"]="The Brood of Onyxia",["minLevel"]=38,["pre"]={1170},["qlvl"]=43,["quest"]=1171,["npcName"]="Overlord Mok'Morokk"},{["map"]=1445,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:26:6",["t"]="turnin",["npc"]=4500,["npcName"]="Overlord Mok'Morokk",["x"]=0.3629,["title"]="Overlord Mok'Morokk's Concern",["quest"]=1166,["y"]=0.3141},{["map"]=1445,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:26:7",["t"]="turnin",["npc"]=4501,["npcName"]="Draz'Zilb",["x"]=0.3715,["title"]="The Brood of Onyxia",["quest"]=1171,["y"]=0.3309},{["map"]=1445,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:26:8",["t"]="accept",["npc"]=4501,["y"]=0.3309,["x"]=0.3715,["title"]="The Brood of Onyxia",["minLevel"]=38,["pre"]={1171},["qlvl"]=45,["quest"]=1172,["npcName"]="Draz'Zilb"}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:26",["text"]="Brackenwall Village",["detail"]="Ride back north to Brackenwall."},{["goals"]={{["map"]=1445,["x"]=0.534,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:27:1",["text"]="Dragon caves",["y"]=0.747,["t"]="goto"},{["map"]=1445,["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:27:2",["t"]="interact",["y"]=0.7251000000000001,["x"]=0.5356000000000001,["title"]="The Brood of Onyxia",["objName"]="Egg of Onyxia",["quest"]=1172,["object"]=20359}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:27",["text"]="Onyxia's eggs",["detail"]="The Eggs of Onyxia lie in the dragon caves in the Wyrmbog's south-east, guarded by the scalebanes; smash five."},{["goals"]={{["map"]=1445,["x"]=0.375,["t"]="goto",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:28:1",["text"]="Firemane Scout",["y"]=0.6829999999999999,["soloWhen"]={{["op"]="<",["frac"]=0.37,["k"]="level",["n"]=45}}},{["map"]=1445,["frac"]=0.37,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:28:2",["t"]="level",["soloWhen"]={{["op"]="<",["frac"]=0.37,["k"]="level",["n"]=45}},["npcName"]="Firemane Scout",["x"]=0.368,["note"]="grind on Firemane Scout",["lvl"]=42,["y"]=0.69,["level"]=45,["spread"]=true,["grind"]=4329}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:28",["text"]="Level 45.37",["soloWhen"]={{["op"]="<",["frac"]=0.37,["k"]="level",["n"]=45}},["detail"]="Overlord Mok'Morokk's challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the Wyrmbog's northern edge to level 45.37 before you ride back north, so you don't come back down for it."},{["goals"]={{["map"]=1445,["note"]="Draz'Zilb, below ground",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:29:1",["t"]="turnin",["npc"]=4501,["npcName"]="Draz'Zilb",["x"]=0.3715,["title"]="The Brood of Onyxia",["quest"]=1172,["y"]=0.3309}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:29",["text"]="Brackenwall Village",["detail"]="Ride back north to Brackenwall."},{["goals"]={},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:30",["text"]="Challenge Overlord Mok'Morokk",["superseded"]=true,["detail"]="These are elite mobs: grouping up is encouraged, look for people to do it with. Challenge Overlord Mok'Morokk needs a group of 3. Skip it if you are alone: the route has you grind the XP back.\nOverlord Mok'Morokk is elite: grouping up is advised. Beat him down until he gives up, then report to Draz'Zilb."},{["id"]="solo:forever/horde/40-50/03-feralas:31",["text"]="Fly to Camp Mojache",["goals"]={{["map"]=1445,["x"]=0.35600000000000004,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:31:1",["text"]="Brackenwall Village flight master",["y"]=0.318,["t"]="goto"},{["id"]="solo:forever/horde/40-50/03-feralas:31:2",["soloSpeedrun"]=true,["location"]="Camp Mojache",["t"]="fly",["node"]=42,["area"]=1099}},["soloSpeedrun"]=true},{["goals"]={{["itemName"]="Encrusted Minerals",["item"]=9589,["quest"]=3128,["map"]=1444,["oi"]=2,["soloSpeedrun"]=true,["fromId"]=5276,["t"]="collect",["id"]="solo:forever/horde/40-50/03-feralas:32:1",["count"]=6,["y"]=0.475,["x"]=0.68,["title"]="Natural Materials",["lvl"]=45,["fromAlso"]="Sprite Darter",["from"]="Sprite Dragon",["fromKind"]="npc",["fromAlsoId"]=5278},{["map"]=1444,["itemName"]="Splintered Log",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=7584,["t"]="collect",["id"]="solo:forever/horde/40-50/03-feralas:32:2",["fromKind"]="npc",["y"]=0.47200000000000003,["x"]=0.54,["title"]="Natural Materials",["lvl"]=46,["item"]=9590,["from"]="Wandering Forest Walker",["quest"]=3128,["count"]=2}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:32",["text"]="Sprite darters and forest walkers",["detail"]="The sprite darters flit over the grove just west of the camp and carry the Encrusted Minerals; the Wandering Forest Walkers, a little further west, carry the Splintered Logs.\nCareful: a Vale Screamer (level 60) flies over the forest west of the camp: keep clear of it."},{["goals"]={{["map"]=1444,["itemName"]="Resilient Sinew",["oi"]=3,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:33:1",["t"]="collect",["y"]=0.6082,["x"]=0.5492,["title"]="Natural Materials",["lvl"]=46,["item"]=9591,["quest"]=3128,["spread"]=true,["count"]=20},{["map"]=1444,["itemName"]="Metallic Fragments",["oi"]=4,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:36:2",["t"]="collect",["item"]=9592,["y"]=0.6082,["x"]=0.5492,["title"]="Natural Materials",["lvl"]=46,["spread"]=true,["fromNpcsAt"]="1;1,2;1;1;2;2,1;2,3;2,3;3,2;3,4,2;3,2,4;4,3;4,2,3,8;3;1;8;8;6,7;8;8;2,3;3,4;3,4,5;7,6;6;7,6;6,7;7",["quest"]=3128,["count"]=40}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:step:36",["text"]="Frayfeather hippogryphs",["detail"]="South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."},{["goals"]={{["map"]=1444,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:34:1",["t"]="accept",["npc"]=14637,["npcName"]="Zorbin Fandazzle",["x"]=0.4481,["title"]="Zapped Giants",["minLevel"]=45,["qlvl"]=48,["quest"]=7003,["y"]=0.43420000000000003},{["map"]=1444,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:34:2",["t"]="accept",["npc"]=14637,["npcName"]="Zorbin Fandazzle",["x"]=0.4481,["title"]="Fuel for the Zapping",["minLevel"]=45,["qlvl"]=48,["quest"]=7721,["y"]=0.43420000000000003}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:34",["text"]="Zorbin Fandazzle",["detail"]="Ride north-west to the Forgotten Coast; Zorbin Fandazzle waits on the dock."},{["goals"]={{["map"]=1444,["itemName"]="Yeh'kinya's Bramble",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:38:1",["t"]="use",["y"]=0.38,["x"]=0.45,["title"]="Screecher Spirits",["item"]=10699,["quest"]=3520,["carriedTo"]="forever/horde/40-50/04-tanaris"},{["map"]=1444,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:38:2",["t"]="talk",["npc"]=8612,["npcName"]="Screecher Spirit",["x"]=0.46,["title"]="Screecher Spirits",["y"]=0.37689999999999996,["quest"]=3520,["carriedTo"]="forever/horde/40-50/04-tanaris"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:step:38",["text"]="Rogue Vale screechers",["detail"]="Rogue Vale opens just north of Zorbin Fandazzle's dock. Kill a Rogue Vale Screecher, use Yeh'kinya's Bramble on its body before you loot it, then talk to the spirit that rises: it is friendly. Three spirits in all."},{["goals"]={{["itemName"]="Water Elemental Core",["item"]=18958,["quest"]=7721,["map"]=1444,["fromId"]=5461,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:39:1",["fromAlso"]="Sea Spray",["t"]="collect",["title"]="Fuel for the Zapping",["y"]=0.486,["x"]=0.44939999999999997,["count"]=10,["from"]="Sea Elemental",["note"]="Water Elemental Core, from the Sea Sprays",["lvl"]=49,["fromKind"]="npc",["fromAlsoId"]=5462},{["map"]=1444,["itemName"]="Zorbin's Ultra-Shrinker",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:39:2",["t"]="use",["y"]=0.49079999999999996,["x"]=0.4412,["title"]="Zapped Giants",["item"]=18904,["quest"]=7003,["note"]="Zorbin's Ultra-Shrinker, on the Wave and Deep Striders in the water"},{["map"]=1444,["itemName"]="Miniaturization Residue",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:39:3",["t"]="collect",["y"]=0.49079999999999996,["x"]=0.4412,["title"]="Zapped Giants",["item"]=18956,["quest"]=7003,["spread"]=true,["count"]=15}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:step:39",["text"]="Forgotten Coast: kill these as you meet them",["detail"]="The Sea Sprays (47-48) wash along the shore just south of the dock: they drop the Water Elemental Cores as well as the Sea Elementals (48-49) do. The Wave and Deep Striders (47-49) wade in the water off the same beach: zap them with Zorbin's Ultra-Shrinker first, and shrunken they lose their elite strength. Leave the Land Walkers and Cliff Giants (48-50) of the northern hills for your next Feralas visit.\nThe Ultra-Shrinker lasts two hours: hand both quests back to Zorbin Fandazzle before you leave the coast."},{["goals"]={{["map"]=1444,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:40:1",["t"]="turnin",["npc"]=14637,["npcName"]="Zorbin Fandazzle",["x"]=0.4481,["title"]="Zapped Giants",["quest"]=7003,["y"]=0.43420000000000003},{["map"]=1444,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:40:2",["t"]="turnin",["npc"]=14637,["npcName"]="Zorbin Fandazzle",["x"]=0.4481,["title"]="Fuel for the Zapping",["quest"]=7721,["y"]=0.43420000000000003}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:step:40",["text"]="Zorbin Fandazzle",["detail"]="Back to Zorbin Fandazzle on the dock."},{["goals"]={{["itemName"]="Rage Scar Yeti Hide",["item"]=18947,["quest"]=7734,["map"]=1444,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=7848,["t"]="collect",["id"]="solo:forever/horde/40-50/03-feralas:38:1",["count"]=10,["y"]=0.3079,["x"]=0.518,["title"]="Improved Quality",["lvl"]=46,["fromAlso"]="Rage Scar Yeti",["from"]="Lurking Feral Scar",["fromKind"]="npc",["fromAlsoId"]=5296},{["map"]=1444,["itemName"]="Perfect Yeti Hide",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:38:2",["t"]="collect",["y"]=0.3079,["x"]=0.518,["item"]=18972,["lvl"]=46,["optional"]=true,["note"]="Perfect Yeti Hide, a rare drop"},{["itemName"]="Perfect Yeti Hide",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:38:3",["t"]="accept",["title"]="Perfect Yeti Hide",["item"]=18972,["qlvl"]=48,["pre"]={2822},["minLevel"]=40,["quest"]=7738,["optional"]=true}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:38",["text"]="Rage Scar yetis",["detail"]="On the way back south-east from the coast, the Rage Scar yetis live around the caves in the hills by the road. Any of them can also drop a Perfect Yeti Hide, which starts a quest of its own."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:step:42",["text"]="Camp Mojache",["goals"]={{["map"]=1444,["note"]="Jangdor Swiftstrider, inside",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:39:1",["t"]="turnin",["npc"]=7854,["npcName"]="Jangdor Swiftstrider",["x"]=0.7443000000000001,["title"]="Improved Quality",["quest"]=7734,["y"]=0.4291},{["map"]=1444,["optional"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:39:2",["t"]="turnin",["npc"]=7854,["npcName"]="Jangdor Swiftstrider",["x"]=0.7443000000000001,["title"]="Perfect Yeti Hide",["quest"]=7738,["y"]=0.4291},{["map"]=1444,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/03-feralas:39:3",["t"]="turnin",["npc"]=8115,["npcName"]="Witch Doctor Uzer'i",["x"]=0.7442,["title"]="Natural Materials",["quest"]=3128,["y"]=0.4336},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/03-feralas:goal:42:4",["text"]="Talo Thornhoof's Northspring harpies (48-50) wait for your Feralas visit at about 51: keep the quest.",["t"]="note",["soloSpeedrun"]=true}},["soloSpeedrun"]=true}},["max"]=48,["soloSpeedrun"]=true,["min"]=46,["availability"]="source-listed",["name"]="Feralas, Dustwallow Marsh & Swamp of Sorrows (solo 46-48)",["category"]="Leveling",["zoneName"]="Feralas",["faction"]="Horde",["refreshRevision"]="forever-20261117-b753c783",["next"]="solo:forever/horde/40-50/04-tanaris"} end},
{id="solo:forever/horde/40-50/04-tanaris",faction="Horde",races=nil,build=function()return {["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; adapted Forever solo leveling plan",["zone"]=1446,["id"]="solo:forever/horde/40-50/04-tanaris",["steps"]={{["id"]="solo:forever/horde/40-50/04-tanaris:1",["text"]="Feralas",["goals"]={{["map"]=1444,["x"]=0.754,["y"]=0.44299999999999995,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:1:1",["t"]="goto",["text"]="Camp Mojache",["area"]=1099}},["soloSpeedrun"]=true},{["id"]="solo:forever/horde/40-50/04-tanaris:2",["text"]="Fly to Gadgetzan",["goals"]={{["map"]=1444,["x"]=0.754,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:2:1",["text"]="Camp Mojache flight master",["y"]=0.44299999999999995,["t"]="goto"},{["id"]="solo:forever/horde/40-50/04-tanaris:2:2",["soloSpeedrun"]=true,["location"]="Gadgetzan",["t"]="fly",["node"]=40,["area"]=976}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1446,["note"]="Tran'rek, beside the wind rider master",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:3:1",["t"]="accept",["npc"]=7876,["npcName"]="Tran'rek",["x"]=0.5157,["title"]="Thistleshrub Valley",["minLevel"]=45,["qlvl"]=50,["quest"]=3362,["y"]=0.2676},{["map"]=1446,["note"]="Andi Lynn: keep it, the Dunemaul ogres and Gor'marok (49) wait for the Broken Pillar at about 52, at the end of 40-50/06",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:3:2",["t"]="accept",["npc"]=11758,["npcName"]="Andi Lynn",["x"]=0.5282,["title"]="The Dunemaul Compound",["minLevel"]=44,["qlvl"]=49,["quest"]=5863,["y"]=0.27399999999999997},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:3:3",["t"]="turnin",["npc"]=7407,["npcName"]="Chief Engineer Bilgewhizzle",["x"]=0.5246,["title"]="Into the Field",["quest"]=243,["y"]=0.2851},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:3:4",["t"]="accept",["npc"]=7407,["y"]=0.2851,["x"]=0.5246,["title"]="Slake That Thirst",["minLevel"]=38,["pre"]={243},["qlvl"]=46,["quest"]=379,["npcName"]="Chief Engineer Bilgewhizzle"},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:3:5",["t"]="sethome",["npc"]=7733,["npcName"]="Innkeeper Fizzgrimble",["x"]=0.5251,["location"]="Gadgetzan",["y"]=0.2791,["area"]=976},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:3:6",["t"]="accept",["npc"]=7564,["npcName"]="Marin Noggenfogger",["x"]=0.5181,["title"]="The Thirsty Goblin",["minLevel"]=44,["qlvl"]=49,["quest"]=2605,["y"]=0.2866}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:3",["text"]="Gadgetzan",["detail"]="The flight lands beside Tran'rek. Take the town's quests before riding west to Sandsorrow Watch."},{["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:4:1",["t"]="accept",["npc"]=7724,["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={992}},{["neg"]=true,["k"]="turnedin",["q"]=992}},["npcName"]="Senior Surveyor Fizzledowser",["x"]=0.5021,["title"]="Gadgetzan Water Survey",["minLevel"]=38,["qlvl"]=46,["quest"]=992,["y"]=0.2748}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:4",["text"]="Senior Surveyor Fizzledowser",["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={992}},{["neg"]=true,["k"]="turnedin",["q"]=992}},["detail"]="You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:5",["text"]="Gadgetzan",["superseded"]=true,["detail"]="For your Zul'Farrak run, after Sandsorrow Watch: Chief Engineer Bilgewhizzle, by the water tower, wants his Divino-matic Rod back; Tran'rek his scarab shells and Trenton Lighthammer Troll Temper, if you have not taken those yet."},{["id"]="solo:forever/horde/40-50/04-tanaris:4",["text"]="Tanaris",["goals"]={{["map"]=1446,["x"]=0.39,["y"]=0.29,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:4:1",["t"]="goto",["text"]="Sandsorrow Watch",["area"]=979}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1446,["itemName"]="Untapped Dowsing Widget",["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:5:1",["t"]="use",["y"]=0.292,["x"]=0.39,["title"]="Gadgetzan Water Survey",["quest"]=992,["item"]=8584},{["map"]=1446,["itemName"]="Tapped Dowsing Widget",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=144052,["t"]="collect",["id"]="solo:forever/horde/40-50/04-tanaris:5:2",["y"]=0.292,["x"]=0.39,["count"]=1,["from"]="Sandsorrow Watch Water Hole",["quest"]=992,["item"]=8585,["fromKind"]="object",["title"]="Gadgetzan Water Survey"}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:5",["text"]="Sandsorrow Watch",["detail"]="West of Gadgetzan, use the Untapped Dowsing Widget beside the water hole in the troll camp."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:8",["text"]="Zul'Farrak",["superseded"]=true,["detail"]="Zul'Farrak is a dungeon for a group of five; its quests here are level 45 to 47. Its gate lies about 400 yards north of the troll camp's water hole.\nInside: the Scarabs drop the shells, every Sandfury troll can drop Troll Temper, and Sergeant Bly carries the Divino-matic Rod."},{["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:6:1",["t"]="turnin",["npc"]=7724,["npcName"]="Senior Surveyor Fizzledowser",["x"]=0.5021,["title"]="Gadgetzan Water Survey",["quest"]=992,["y"]=0.2748},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:6:2",["t"]="accept",["npc"]=7724,["y"]=0.2748,["x"]=0.5021,["title"]="Noxious Lair Investigation",["minLevel"]=39,["pre"]={992},["qlvl"]=47,["quest"]=82,["npcName"]="Senior Surveyor Fizzledowser"}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:6",["text"]="Senior Surveyor Fizzledowser",["detail"]="Back east to Fizzledowser on the west side of Gadgetzan; Marvon Rivetseeker is south from there."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:10",["text"]="Tran'rek",["superseded"]=true,["detail"]="Your Zul'Farrak scarab shells: Tran'rek, beside the wind rider master."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:11",["text"]="Chief Engineer Bilgewhizzle",["superseded"]=true,["detail"]="The Divino-matic Rod: Chief Engineer Bilgewhizzle, by the water tower."},{["goals"]={},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:12",["text"]="Trenton Lighthammer",["superseded"]=true,["detail"]="The Troll Temper: Trenton Lighthammer, a short walk from the flight master."},{["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:7:1",["t"]="accept",["npc"]=7771,["npcName"]="Marvon Rivetseeker",["x"]=0.5271,["title"]="Gahz'ridian",["minLevel"]=43,["qlvl"]=48,["quest"]=3161,["y"]=0.4592}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:7",["text"]="Marvon Rivetseeker",["detail"]="West along the road south; Marvon Rivetseeker camps by the ruins at the Broken Pillar. Put on his Gahz'ridian Detector: it shows the buried ornaments, here and around the Dunemaul Compound."},{["goals"]={{["map"]=1446,["itemName"]="Gahz'ridian Ornament",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=140971,["t"]="collect",["id"]="solo:forever/horde/40-50/04-tanaris:8:1",["y"]=0.45299999999999996,["x"]=0.523,["count"]=30,["from"]="Gahz'ridian",["quest"]=3161,["item"]=8443,["fromKind"]="object",["title"]="Gahz'ridian"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:14",["text"]="Gahz'ridian ornaments",["detail"]="Dig up the Gahz'ridian ornaments around the Broken Pillar and north of the Dunemaul Compound. Leave the ogres for now: Gor'marok the Ravager is 49 and the Brutes 46-48; the Dunemaul Compound comes at the end of 40-50/06, at about 52."},{["goals"]={{["itemName"]="Centipaar Insect Parts",["item"]=8587,["quest"]=82,["map"]=1446,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=5458,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:15:1",["y"]=0.4268,["x"]=0.3575,["title"]="Noxious Lair Investigation",["from"]="Centipaar Worker",["count"]=5,["fromAlso"]="Centipaar Tunneler",["fromKind"]="npc",["fromAlsoId"]=5459}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:15",["text"]="The Noxious Lair",["detail"]="West, the Centipaar insects swarm around their hives; any of them drops the parts.\nCareful: Centipaar Swarmers cast Silithid Swarm both in and out of combat, which brings small adds that interrupt you. The Sandreavers are 49-50: take the Workers and Tunnelers."},{["goals"]={{["map"]=1446,["itemName"]="OOX-17/TN Distress Beacon",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:16:1",["t"]="collect",["y"]=0.2789,["x"]=0.4484,["item"]=8623,["lvl"]=45,["optional"]=true,["spread"]=true,["note"]="OOX-17/TN Distress Beacon, a rare drop"},{["map"]=1446,["itemName"]="Laden Dew Gland",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=5481,["t"]="collect",["id"]="solo:forever/horde/40-50/04-tanaris:10:4",["fromKind"]="npc",["y"]=0.6609999999999999,["x"]=0.292,["title"]="The Thirsty Goblin",["lvl"]=48,["item"]=8428,["from"]="Thistleshrub Dew Collector",["quest"]=2605,["count"]=1}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:16",["text"]="Thistleshrub Valley: kill these as you meet them",["detail"]="West of the compound the cactus creatures fill the valley; only the Dew Collectors (47-48) carry a dew gland. Most mobs in Tanaris can drop OOX-17/TN's distress beacon, rarely: keep it if you see one.\nCareful: The other thistleshrub mobs in the area are level 48-50 and wander a lot, so you can easily pull extra mobs: take the Dew Collectors at the valley's edge, and leave Tran'rek's Gnarled Thistleshrubs and Rootshapers for the Broken Pillar ride into Un'Goro at about 51."},{["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:11:1",["t"]="accept",["npc"]=5955,["escort"]=true,["npcName"]="Tooga",["x"]=0.3,["title"]="Tooga's Quest",["y"]=0.65,["qlvl"]=50,["limit"]=1800,["quest"]=1560,["minLevel"]=40},{["map"]=1446,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:17:2",["t"]="complete",["objs"]={{["count"]=1,["text"]="Lead Tooga to Torta"}},["y"]=0.25670000000000004,["x"]=0.6658,["title"]="Tooga's Quest",["quest"]=1560,["escort"]=true}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:17",["text"]="Tooga's escort",["detail"]="Tooga waits in the valley. Walk him all the way to his wife Torta in Steamwheedle Port, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. Yeh'kinya stands in the port too."},{["id"]="solo:forever/horde/40-50/04-tanaris:12",["text"]="Steamwheedle Port",["goals"]={{["map"]=1446,["note"]="Torta, Steamwheedle Port",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:12:1",["t"]="turnin",["npc"]=6015,["npcName"]="Torta",["x"]=0.6658,["title"]="Tooga's Quest",["quest"]=1560,["y"]=0.25670000000000004},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:12:2",["t"]="turnin",["npc"]=8579,["npcName"]="Yeh'kinya",["x"]=0.6698999999999999,["title"]="Screecher Spirits",["quest"]=3520,["y"]=0.2236}},["soloSpeedrun"]=true},{["goals"]={{["itemName"]="Wastewander Water Pouch",["item"]=8483,["quest"]=379,["map"]=1446,["oi"]=1,["soloSpeedrun"]=true,["fromId"]=5617,["t"]="collect",["id"]="solo:forever/horde/40-50/04-tanaris:13:1",["count"]=5,["y"]=0.23399999999999999,["x"]=0.6,["title"]="Slake That Thirst",["lvl"]=42,["fromAlso"]="Wastewander Thief",["from"]="Wastewander Shadow Mage",["fromKind"]="npc",["fromAlsoId"]=5616}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:13",["text"]="Slake That Thirst",["detail"]="Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and Shadow Bolt. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:20",["text"]="Gadgetzan",["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:14:2",["t"]="turnin",["npc"]=7407,["npcName"]="Chief Engineer Bilgewhizzle",["x"]=0.5246,["title"]="Slake That Thirst",["quest"]=379,["y"]=0.2851},{["id"]="solo:forever/horde/40-50/04-tanaris:14:3",["text"]="Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts Tanaris Field Sampling, a two-hour timer, so use it on the way back north from Scrimshank's hive.",["t"]="note",["soloSpeedrun"]=true}},["soloSpeedrun"]=true},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:21",["text"]="Gadgetzan",["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:15:1",["t"]="turnin",["npc"]=7564,["npcName"]="Marin Noggenfogger",["x"]=0.5181,["title"]="The Thirsty Goblin",["quest"]=2605,["y"]=0.2866},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:15:2",["t"]="accept",["npc"]=7564,["y"]=0.2866,["x"]=0.5181,["title"]="In Good Taste",["minLevel"]=44,["pre"]={2605},["qlvl"]=49,["quest"]=2606,["npcName"]="Marin Noggenfogger"},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:21:3",["text"]="Keep Tran'rek's Thistleshrub Valley: its Rootshapers (49-50) come with the Dunemaul Compound at the Broken Pillar, on the way into Un'Goro at about 51.",["t"]="note",["soloSpeedrun"]=true},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:15:4",["t"]="turnin",["npc"]=7583,["npcName"]="Sprinkle",["x"]=0.5106,["title"]="In Good Taste",["quest"]=2606,["y"]=0.2687},{["map"]=1446,["note"]="the Violet Tragan grows in the Hinterlands, around level 48",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:15:5",["t"]="accept",["npc"]=7583,["y"]=0.2687,["x"]=0.5106,["title"]="Sprinkle's Secret Ingredient",["minLevel"]=44,["pre"]={2606},["qlvl"]=49,["quest"]=2641,["npcName"]="Sprinkle"},{["map"]=1446,["note"]="Alchemist Pestlezugg, inside",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:15:6",["t"]="turnin",["npc"]=5594,["npcName"]="Alchemist Pestlezugg",["x"]=0.5089,["title"]="Noxious Lair Investigation",["quest"]=82,["y"]=0.2696},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:15:7",["t"]="accept",["npc"]=7724,["y"]=0.2748,["x"]=0.5021,["title"]="The Scrimshank Redemption",["minLevel"]=39,["pre"]={82},["qlvl"]=48,["quest"]=10,["npcName"]="Senior Surveyor Fizzledowser"},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:21:8",["text"]="Andi Lynn's Dunemaul Compound stays in your log for the Broken Pillar at about 52.",["t"]="note",["soloSpeedrun"]=true}},["soloSpeedrun"]=true},{["id"]="solo:forever/horde/40-50/04-tanaris:16",["text"]="Marvon Rivetseeker",["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:16:1",["t"]="turnin",["npc"]=7771,["npcName"]="Marvon Rivetseeker",["x"]=0.5271,["title"]="Gahz'ridian",["quest"]=3161,["y"]=0.4592}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1446,["itemName"]="Scrimshank's Surveying Gear",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=144053,["t"]="collect",["id"]="solo:forever/horde/40-50/04-tanaris:17:1",["quest"]=10,["y"]=0.7120000000000001,["x"]=0.56,["item"]=8593,["from"]="Scrimshank's Surveying Gear",["title"]="The Scrimshank Redemption",["count"]=1,["fromKind"]="object",["note"]="Below ground"}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:17",["text"]="Scrimshank's gear",["detail"]="Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."},{["goals"]={{["optional"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:18:1",["t"]="accept",["title"]="Find OOX-17/TN!",["item"]=8623,["qlvl"]=48,["minLevel"]=43,["quest"]=351,["itemName"]="OOX-17/TN Distress Beacon"},{["map"]=1446,["optional"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:18:2",["t"]="turnin",["npc"]=7784,["npcName"]="Homing Robot OOX-17/TN",["x"]=0.6023,["title"]="Find OOX-17/TN!",["quest"]=351,["y"]=0.6472},{["map"]=1446,["optional"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:18:3",["t"]="accept",["npc"]=7784,["escort"]=true,["npcName"]="Homing Robot OOX-17/TN",["x"]=0.6023,["minLevel"]=43,["title"]="Rescue OOX-17/TN!",["pre"]={351},["qlvl"]=48,["quest"]=648,["y"]=0.6472},{["optional"]=true,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:24:4",["t"]="complete",["objs"]={{["count"]=1,["text"]="Escort OOX-17/TN to Steamwheedle Port"}},["title"]="Rescue OOX-17/TN!",["escort"]=true,["quest"]=648,["carriedTo"]="forever/horde/40-50/06-azshara"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:24",["text"]="OOX-17/TN",["detail"]="Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to Steamwheedle Port; its reward waits with Oglethorpe in Booty Bay.\nCareful: The escort has two ambushes. Three level 47 scorpids attack near the start. Near the end, by the beach, three Wastewander humans attack: one mage and two assassins, around level 44."},{["goals"]={{["itemName"]="Model 4711-FTZ Power Source",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:19:1",["t"]="accept",["title"]="Tanaris Field Sampling",["item"]=8524,["qlvl"]=46,["minLevel"]=38,["pre"]={379},["limit"]=7200,["quest"]=654,["note"]="Use the Model 4711-FTZ Power Source"},{["map"]=1446,["itemName"]="Acceptable Hyena Sample",["oi"]=2,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:19:2",["t"]="collect",["y"]=0.316,["x"]=0.502,["title"]="Tanaris Field Sampling",["item"]=9441,["quest"]=654,["count"]=8},{["map"]=1446,["itemName"]="Acceptable Basilisk Sample",["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:19:3",["t"]="collect",["y"]=0.31,["x"]=0.494,["title"]="Tanaris Field Sampling",["item"]=9440,["quest"]=654,["count"]=8},{["map"]=1446,["itemName"]="Acceptable Scorpid Sample",["oi"]=3,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:19:4",["t"]="collect",["y"]=0.312,["x"]=0.532,["title"]="Tanaris Field Sampling",["item"]=9438,["quest"]=654,["count"]=8}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:19",["text"]="Tanaris Field Sampling",["detail"]="Back north, just south of Gadgetzan, use the Model 4711-FTZ Power Source now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:26",["text"]="Gadgetzan",["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:20:1",["t"]="turnin",["npc"]=7407,["npcName"]="Chief Engineer Bilgewhizzle",["x"]=0.5246,["title"]="Tanaris Field Sampling",["quest"]=654,["y"]=0.2851},{["map"]=1446,["note"]="for Apothecary Zinge in the Undercity, around level 52",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:20:2",["t"]="accept",["npc"]=7407,["y"]=0.2851,["x"]=0.5246,["title"]="Return to Apothecary Zinge",["minLevel"]=38,["pre"]={654},["qlvl"]=46,["quest"]=864,["npcName"]="Chief Engineer Bilgewhizzle"},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:20:3",["t"]="turnin",["npc"]=7724,["npcName"]="Senior Surveyor Fizzledowser",["x"]=0.5021,["title"]="The Scrimshank Redemption",["quest"]=10,["y"]=0.2748},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:20:4",["t"]="accept",["npc"]=7724,["y"]=0.2748,["x"]=0.5021,["title"]="Insect Part Analysis",["minLevel"]=39,["pre"]={10},["qlvl"]=48,["quest"]=110,["npcName"]="Senior Surveyor Fizzledowser"},{["map"]=1446,["note"]="Alchemist Pestlezugg, inside",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:20:5",["t"]="turnin",["npc"]=5594,["npcName"]="Alchemist Pestlezugg",["x"]=0.5089,["title"]="Insect Part Analysis",["quest"]=110,["y"]=0.2696},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:20:6",["t"]="accept",["npc"]=5594,["y"]=0.2696,["x"]=0.5089,["title"]="Insect Part Analysis",["minLevel"]=39,["pre"]={110},["qlvl"]=48,["quest"]=113,["npcName"]="Alchemist Pestlezugg"},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:20:7",["t"]="turnin",["npc"]=7724,["npcName"]="Senior Surveyor Fizzledowser",["x"]=0.5021,["title"]="Insect Part Analysis",["quest"]=113,["y"]=0.2748},{["map"]=1446,["note"]="for Zilzibin Drumlore in Orgrimmar, around level 50",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:20:8",["t"]="accept",["npc"]=7724,["y"]=0.2748,["x"]=0.5021,["title"]="Rise of the Silithid",["minLevel"]=39,["pre"]={113},["qlvl"]=48,["quest"]=32,["npcName"]="Senior Surveyor Fizzledowser"}},["soloSpeedrun"]=true},{["id"]="solo:forever/horde/40-50/04-tanaris:21",["text"]="Boat to Powderfuse Port",["goals"]={{["map"]=1446,["x"]=0.6759999999999999,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:21:1",["text"]="Boat to Powderfuse Port",["y"]=0.231,["t"]="goto"}},["soloSpeedrun"]=true},{["id"]="solo:forever/horde/40-50/04-tanaris:22",["text"]="Into Searing Gorge",["goals"]={{["map"]=1427,["x"]=0.7659999999999999,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:22:1",["text"]="Into Searing Gorge",["y"]=0.5670000000000001,["t"]="goto"}},["soloSpeedrun"]=true},{["id"]="solo:forever/horde/40-50/04-tanaris:23",["text"]="Searing Gorge",["goals"]={{["map"]=1427,["x"]=0.6559999999999999,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:23:1",["text"]="The Grimesilt Dig Site",["y"]=0.622,["t"]="goto"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1427,["note"]="the Wooden Outhouse",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:24:1",["t"]="accept",["y"]=0.6217,["x"]=0.6559,["title"]="Caught!",["objName"]="Wooden Outhouse",["object"]=173265,["minLevel"]=43,["quest"]=4449,["qlvl"]=45},{["map"]=1427,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:30:2",["t"]="kill",["npc"]=5839,["y"]=0.6039,["x"]=0.639,["title"]="Caught!",["lvl"]=44,["target"]="Dark Iron Geologist",["quest"]=4449,["count"]=8},{["map"]=1427,["itemName"]="Silk Cloth",["oi"]=2,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:24:3",["t"]="collect",["y"]=0.6039,["x"]=0.639,["title"]="Caught!",["lvl"]=47,["item"]=4306,["quest"]=4449,["spread"]=true,["count"]=15},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:24:4",["t"]="turnin",["y"]=0.6217,["x"]=0.6559,["title"]="Caught!",["objName"]="Wooden Outhouse",["quest"]=4449,["object"]=173265}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:30",["text"]="The Grimesilt Dig Site",["detail"]="From Powderfuse Port, ride into the Searing Gorge by its eastern pass, then west to the dig site. The Wooden Outhouse stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 Silk Cloth (the Auction House sells it)."},{["id"]="solo:forever/horde/40-50/04-tanaris:25",["text"]="Searing Gorge",["goals"]={{["map"]=1427,["x"]=0.377,["y"]=0.265,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:25:1",["t"]="goto",["text"]="Thorium Point",["area"]=1446}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:26:1",["t"]="getfp",["npc"]=3305,["npcName"]="Grisha",["x"]=0.34840000000000004,["location"]="Thorium Point",["y"]=0.30870000000000003,["node"]=75,["area"]=1446},{["map"]=1427,["note"]="The Wanted/Missing/Lost & Found board",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:26:2",["t"]="accept",["y"]=0.2647,["x"]=0.3765,["title"]="STOLEN: Smithing Tuyere and Lookout's Spyglass",["objName"]="Wanted/Missing/Lost & Found",["object"]=179827,["minLevel"]=45,["quest"]=7728,["qlvl"]=48},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:26:3",["t"]="accept",["y"]=0.2647,["x"]=0.3765,["title"]="JOB OPPORTUNITY: Culling the Competition",["objName"]="Wanted/Missing/Lost & Found",["object"]=179827,["minLevel"]=45,["quest"]=7729,["qlvl"]=48},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:26:4",["t"]="accept",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Curse These Fat Fingers",["minLevel"]=45,["qlvl"]=49,["quest"]=7723,["y"]=0.2781},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:26:5",["t"]="accept",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Fiery Menace!",["minLevel"]=45,["qlvl"]=49,["quest"]=7724,["y"]=0.2781},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:26:6",["t"]="accept",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Incendosaurs? Whateverosaur is More Like It",["minLevel"]=45,["qlvl"]=49,["quest"]=7727,["y"]=0.2781}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:32",["text"]="Thorium Point",["detail"]="Ride north-west across the gorge; Thorium Point is the scaffolded camp in the north-west."},{["goals"]={{["map"]=1427,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:33:1",["t"]="kill",["npc"]=5846,["y"]=0.3195,["x"]=0.3803,["title"]="JOB OPPORTUNITY: Culling the Competition",["target"]="Dark Iron Taskmaster",["quest"]=7729,["count"]=15},{["map"]=1427,["oi"]=2,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:27:2",["t"]="kill",["npc"]=5844,["y"]=0.3204,["x"]=0.4025,["title"]="JOB OPPORTUNITY: Culling the Competition",["lvl"]=46,["target"]="Dark Iron Slaver",["count"]=15,["quest"]=7729,["spread"]=true},{["map"]=1427,["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:27:3",["t"]="kill",["npc"]=5854,["y"]=0.3872,["x"]=0.4476,["title"]="Curse These Fat Fingers",["lvl"]=49,["target"]="Heavy War Golem",["quest"]=7723,["count"]=20}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:33",["text"]="The Cauldron's slavers and golems",["detail"]="Ride south from Thorium Point into the Cauldron: the Dark Iron Taskmasters and Slavers drive the slaves on the paths, and the Heavy War Golems patrol the floor below Velarok Windblade. Careful: the biggest golems are 49: pull them one at a time."},{["goals"]={{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:28:1",["t"]="accept",["npc"]=8479,["npcName"]="Velarok Windblade",["x"]=0.3906,["title"]="Divine Retribution",["minLevel"]=40,["qlvl"]=48,["quest"]=3441,["y"]=0.3899}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:28",["text"]="Velarok Windblade",["detail"]="Velarok Windblade stands alone south of Thorium Point, at the edge of the Cauldron. Listen to his story."},{["id"]="solo:forever/horde/40-50/04-tanaris:29",["text"]="Divine Retribution",["goals"]={{["map"]=1427,["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:29:1",["t"]="talk",["npc"]=8479,["npcName"]="Velarok Windblade",["x"]=0.391,["title"]="Divine Retribution",["quest"]=3441,["y"]=0.39}},["soloSpeedrun"]=true},{["id"]="solo:forever/horde/40-50/04-tanaris:30",["text"]="Velarok Windblade",["goals"]={{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:30:1",["t"]="turnin",["npc"]=8479,["npcName"]="Velarok Windblade",["x"]=0.3906,["title"]="Divine Retribution",["quest"]=3441,["y"]=0.3899},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:30:2",["t"]="accept",["npc"]=8479,["y"]=0.3899,["x"]=0.3906,["title"]="The Flawless Flame",["minLevel"]=40,["pre"]={3441},["qlvl"]=48,["quest"]=3442,["npcName"]="Velarok Windblade"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1427,["itemName"]="Grimesilt Outhouse Key",["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:31:1",["t"]="collect",["y"]=0.3786,["x"]=0.3914,["item"]=11818,["lvl"]=48,["optional"]=true,["spread"]=true,["note"]="Grimesilt Outhouse Key, a rare drop"},{["map"]=1427,["itemName"]="Heart of Flame",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:37:2",["t"]="collect",["y"]=0.36729999999999996,["x"]=0.4069,["title"]="The Flawless Flame",["item"]=10509,["quest"]=3442,["spread"]=true,["count"]=4},{["map"]=1427,["itemName"]="Golem Oil",["oi"]=2,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:31:3",["t"]="collect",["y"]=0.3861,["x"]=0.4249,["title"]="The Flawless Flame",["lvl"]=49,["item"]=10511,["quest"]=3442,["spread"]=true,["count"]=4},{["map"]=1427,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:37:4",["t"]="kill",["npc"]=5858,["y"]=0.33340000000000003,["x"]=0.3801,["title"]="Fiery Menace!",["target"]="Searing Lava Spider",["count"]=20,["quest"]=7724,["spread"]=true},{["map"]=1427,["note"]="Below ground",["oi"]=1,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:31:5",["t"]="kill",["npc"]=9318,["y"]=0.2826,["x"]=0.4338,["title"]="Incendosaurs? Whateverosaur is More Like It",["lvl"]=49,["target"]="Incendosaur",["quest"]=7727,["count"]=20}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:37",["text"]="Searing Gorge: kill these as you meet them",["detail"]="Heavy War Golems patrol the Cauldron below Velarok Windblade and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the Grimesilt Outhouse Key: keep it.\nThe Searing Lava Spiders roam the plateaus and lava pools in the south-west of the gorge.\nThe Slag Pit opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee. The biggest Incendosaurs and Lava Spiders are 49: pull them one at a time."},{["id"]="solo:forever/horde/40-50/04-tanaris:32",["text"]="Velarok Windblade",["goals"]={{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:32:1",["t"]="turnin",["npc"]=8479,["npcName"]="Velarok Windblade",["x"]=0.3906,["title"]="The Flawless Flame",["quest"]=3442,["y"]=0.3899},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:32:2",["t"]="accept",["npc"]=8479,["y"]=0.3899,["x"]=0.3906,["title"]="Forging the Shaft",["minLevel"]=40,["pre"]={3442},["qlvl"]=48,["quest"]=3443,["npcName"]="Velarok Windblade"}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:33:1",["t"]="turnin",["npc"]=14626,["npcName"]="Taskmaster Scrange",["x"]=0.3897,["title"]="JOB OPPORTUNITY: Culling the Competition",["quest"]=7729,["y"]=0.2751},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:33:2",["t"]="turnin",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Incendosaurs? Whateverosaur is More Like It",["quest"]=7727,["y"]=0.2781},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:33:3",["t"]="turnin",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Fiery Menace!",["quest"]=7724,["y"]=0.2781},{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:33:4",["t"]="turnin",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Curse These Fat Fingers",["quest"]=7723,["y"]=0.2781}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:33",["text"]="Thorium Point",["detail"]="Ride back north to Thorium Point, just past Velarok Windblade."},{["goals"]={{["map"]=1427,["itemName"]="Thorium Plated Dagger",["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:40:1",["t"]="collect",["item"]=10551,["y"]=0.2783,["x"]=0.39909999999999995,["title"]="Forging the Shaft",["lvl"]=48,["spread"]=true,["fromNpcsAt"]="1,6;5;6,5;6,5;1,6,5;1,5,4,6;7;7,5;7;1,6,5;7;3,8;9;2,3;5,6;1,5,6;1,5,6;1,5,6;1,5,6",["quest"]=3443,["count"]=8},{["map"]=1427,["itemName"]="Smithing Tuyere",["oi"]=1,["soloSpeedrun"]=true,["fromId"]=5840,["t"]="collect",["id"]="solo:forever/horde/40-50/04-tanaris:34:2",["fromKind"]="npc",["y"]=0.4833,["x"]=0.40009999999999996,["title"]="STOLEN: Smithing Tuyere and Lookout's Spyglass",["lvl"]=47,["item"]=18959,["from"]="Dark Iron Steamsmith",["quest"]=7728,["count"]=1}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:40",["text"]="The Steamsmiths' furnaces",["detail"]="The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a Thorium Plated Dagger, one in ten the Smithing Tuyere. Slaves, Slavers and Taskmasters carry daggers too."},{["id"]="solo:forever/horde/40-50/04-tanaris:35",["text"]="Velarok Windblade",["goals"]={{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:35:1",["t"]="turnin",["npc"]=8479,["npcName"]="Velarok Windblade",["x"]=0.3906,["title"]="Forging the Shaft",["quest"]=3443,["y"]=0.3899},{["id"]="solo:forever/horde/40-50/04-tanaris:35:2",["text"]="His next request needs the Symbol of Ragnaros from elite cultists: leave it.",["t"]="note",["soloSpeedrun"]=true}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1427,["itemName"]="Lookout's Spyglass",["oi"]=2,["soloSpeedrun"]=true,["fromId"]=8566,["t"]="collect",["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:goal:42:1",["fromKind"]="npc",["y"]=0.5192,["x"]=0.3371,["title"]="STOLEN: Smithing Tuyere and Lookout's Spyglass",["from"]="Dark Iron Lookout",["item"]=18960,["spread"]=true,["quest"]=7728,["count"]=1}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:42",["text"]="Dark Iron Lookouts",["detail"]="The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the Lookout's Spyglass."},{["goals"]={{["optional"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:38:1",["t"]="accept",["title"]="The Key to Freedom",["item"]=11818,["qlvl"]=47,["minLevel"]=43,["quest"]=4451,["itemName"]="Grimesilt Outhouse Key"},{["map"]=1427,["optional"]=true,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:38:2",["t"]="turnin",["y"]=0.6217,["x"]=0.6559,["title"]="The Key to Freedom",["objName"]="Wooden Outhouse",["quest"]=4451,["object"]=173265}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:38",["text"]="The Key to Freedom",["detail"]="Only with the Grimesilt Outhouse Key: back east to the Wooden Outhouse at the dig site."},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/04-tanaris:step:44",["text"]="Thorium Point",["goals"]={{["map"]=1427,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/04-tanaris:39:2",["t"]="turnin",["npc"]=14626,["npcName"]="Taskmaster Scrange",["x"]=0.3897,["title"]="STOLEN: Smithing Tuyere and Lookout's Spyglass",["quest"]=7728,["y"]=0.2751}},["soloSpeedrun"]=true}},["max"]=49,["soloSpeedrun"]=true,["min"]=48,["availability"]="source-listed",["name"]="Tanaris & Searing Gorge (solo 48-49)",["category"]="Leveling",["zoneName"]="Tanaris",["faction"]="Horde",["refreshRevision"]="forever-20261117-b753c783",["next"]="solo:forever/horde/40-50/05-the-hinterlands"} end},
