e},{["goals"]={{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/06-azshara:65:1",["t"]="turnin",["npc"]=7771,["npcName"]="Marvon Rivetseeker",["x"]=0.5271,["title"]="The Sunken Temple",["quest"]=3380,["y"]=0.4592},{["map"]=1446,["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/06-azshara:65:2",["t"]="accept",["npc"]=7771,["y"]=0.4592,["x"]=0.5271,["title"]="The Stone Circle",["minLevel"]=46,["pre"]={3380,3445},["qlvl"]=51,["quest"]=3444,["npcName"]="Marvon Rivetseeker"},{["id"]="solo:forever/horde/40-50/06-azshara:65:3",["text"]="Keep The Stone Circle: Marvon Rivetseeker's chest is opened on a later visit.",["t"]="note",["soloSpeedrun"]=true}},["soloSpeedrun"]=true,["id"]="solo:forever/horde/40-50/06-azshara:65",["text"]="Marvon Rivetseeker",["detail"]="Ride south along the road to the Broken Pillar; Marvon Rivetseeker camps beside it. From here the road west leads down into Un'Goro Crater, where the next guide starts."},{["goals"]={{["map"]=1446,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/06-azshara:goal:56:1",["t"]="kill",["npc"]=5474,["carriedTo"]="forever/horde/50-60/01-un-goro-crater",["y"]=0.5315,["x"]=0.4268,["title"]="The Dunemaul Compound",["lvl"]=48,["target"]="Dunemaul Brute",["quest"]=5863,["spread"]=true,["count"]=10},{["map"]=1446,["oi"]=2,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/06-azshara:goal:56:2",["t"]="kill",["npc"]=5472,["carriedTo"]="forever/horde/50-60/01-un-goro-crater",["y"]=0.5334,["x"]=0.42200000000000004,["title"]="The Dunemaul Compound",["lvl"]=47,["target"]="Dunemaul Enforcer",["quest"]=5863,["spread"]=true,["count"]=10},{["map"]=1446,["note"]="Below ground",["oi"]=3,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/06-azshara:goal:56:3",["t"]="kill",["npc"]=12046,["y"]=0.578,["x"]=0.415,["title"]="The Dunemaul Compound",["target"]="Gor'marok the Ravager",["count"]=1,["quest"]=5863,["carriedTo"]="forever/horde/50-60/01-un-goro-crater"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/06-azshara:step:56",["text"]="The Dunemaul Compound",["detail"]="South of the Broken Pillar the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end: Andi Lynn's quest, carried from your first Tanaris visit."},{["goals"]={{["map"]=1446,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/06-azshara:goal:57:1",["t"]="kill",["npc"]=5490,["y"]=0.664,["x"]=0.2965,["carriedTo"]="forever/horde/50-60/01-un-goro-crater",["lvl"]=49,["target"]="Gnarled Thistleshrub",["count"]=8,["quest"]=3362,["title"]="Thistleshrub Valley"},{["map"]=1446,["oi"]=2,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/06-azshara:goal:57:2",["t"]="kill",["npc"]=5485,["y"]=0.6635,["x"]=0.2969,["carriedTo"]="forever/horde/50-60/01-un-goro-crater",["lvl"]=50,["target"]="Thistleshrub Rootshaper",["count"]=8,["quest"]=3362,["title"]="Thistleshrub Valley"}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/40-50/06-azshara:step:57",["text"]="Thistleshrub Valley",["detail"]="West from the compound, on the way to Un'Goro's ramp: Thistleshrub Valley's Gnarled Thistleshrubs and Rootshapers (48-50) are Tran'rek's, carried from your first Tanaris visit. They wander a lot: pull them one at a time. Tran'rek takes them on the next guide's Gadgetzan stop, with Andi Lynn's."}},["max"]=51,["soloSpeedrun"]=true,["min"]=50,["availability"]="source-listed",["name"]="Azshara, Feralas & Stranglethorn Vale (solo 50-51)",["category"]="Leveling",["zoneName"]="Azshara",["faction"]="Horde",["refreshRevision"]="forever-20261117-b753c783",["next"]="solo:forever/horde/50-60/01-un-goro-crater"} end},
