y"]=0.2637},{["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/50-60/05-eastern-plaguelands:goal:24:2",["text"]="Keep the termites: Mickey Levine at the Bulwark takes them on the next guide's ride into the Western Plaguelands.",["t"]="note",["soloSpeedrun"]=true}},["soloSpeedrun"]=true},{["goals"]={{["map"]=1423,["x"]=0.495,["y"]=0.434,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/50-60/05-eastern-plaguelands:goal:25:1",["t"]="goto",["text"]="Noxious Plaguebat",["soloWhen"]={{["op"]="<",["k"]="level",["n"]=56}}},{["map"]=1423,["oi"]=1,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/50-60/05-eastern-plaguelands:goal:25:2",["t"]="kill",["npc"]=8601,["soloWhen"]={{["op"]="<",["k"]="level",["n"]=56}},["y"]=0.434,["x"]=0.495,["title"]="Un-Life's Little Annoyances",["lvl"]=56,["target"]="Noxious Plaguebat",["quest"]=6042,["count"]=20},{["map"]=1423,["note"]="grind on Noxious Plaguebat",["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/50-60/05-eastern-plaguelands:goal:25:3",["t"]="level",["soloWhen"]={{["op"]="<",["k"]="level",["n"]=56}},["npcName"]="Noxious Plaguebat",["x"]=0.4954,["lvl"]=56,["y"]=0.4336,["level"]=56,["spread"]=true,["grind"]=8601}},["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/50-60/05-eastern-plaguelands:step:25",["text"]="Level 56",["soloWhen"]={{["op"]="<",["k"]="level",["n"]=56}},["detail"]="Top up here to level 56 before the Frenzied Plaguehounds of Northdale (57-58): the Noxious Plaguebats (54-56) over the fields on the way east are at your level, and Nathanos Blightcaller wants twenty of them."},{["goals"]={{["map"]=1423,["oi"]=3,["soloSpeedrun"]=true,["id"]="refresh:forever-20261117-b753c783:solo:forever/horde/50-60/05-eastern-plaguelands:goal:26:1",["t"]="kill",["npc"]=8598,["carriedTo"]="forever/horde/50-60/06-silithus",["y"]=0.37670000000000003,["x"]=0.4905,["title"]="Demon Dogs",["lvl"]=58,[